INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'g7', @ch_id, @gt_id, 'STATIC', 'ESSAY', '已知数轴上 $A$、$B$ 两点分别表示 $-4$ 和 $8$。\n(1) 求 $A$、$B$ 两点之间的距离；\n(2) 若动点 $P$ 从 $A$ 出发以每秒 $2$ 个单位长度的速度向右运动，同时动点 $Q$ 从 $B$ 出发以每秒 $1$ 个单位长度的速度向左运动，设运动时间为 $t$ 秒，当 $PQ = 3$ 时，求 $t$ 的值。', '[]', '{"text":"解：\\n(1) $AB = 8 - (-4) = 12$。\\n(2) $t$ 秒时，$P$ 表示 $-4 + 2t$，$Q$ 表示 $8 - t$。\\n则 $PQ = |(-4 + 2t) - (8 - t)| = |3t - 12| = 3$。\\n当 $3t - 12 = 3$ 时，$3t = 15$，解得 $t = 5$；\\n当 $3t - 12 = -3$ 时，$3t = 9$，解得 $t = 3$。\\n综上，$t = 3$ 或 $t = 5$。"}', '【得分要点】正确用含 $t$ 的代数式表示动点位置，利用绝对值列出 $PQ = |3t-12| = 3$，注意相遇前与相遇后两解均不可遗漏。', NULL, NULL, 4, '["数轴动点","分类讨论","TASK-20261122-002"]', '{"diagram":{"title":"数轴示意图","width":320,"height":210,"primitives":[{"type":"arrow","x1":28,"y1":108,"x2":292,"y2":108,"color":"#1E293B"},{"type":"line","x1":82,"y1":100,"x2":82,"y2":116,"color":"#1E293B"},{"type":"line","x1":122,"y1":100,"x2":122,"y2":116,"color":"#1E293B"},{"type":"line","x1":160,"y1":98,"x2":160,"y2":118,"color":"#DC2626"},{"type":"line","x1":198,"y1":100,"x2":198,"y2":116,"color":"#1E293B"},{"type":"line","x1":238,"y1":100,"x2":238,"y2":116,"color":"#1E293B"},{"type":"point","x":122,"y":108,"label":"A","color":"#0284C7"},{"type":"point","x":238,"y":108,"label":"B","color":"#059669"},{"type":"text","x":74,"y":124,"text":"-2","color":"#64748B"},{"type":"text","x":114,"y":124,"text":"-1","color":"#64748B"},{"type":"text","x":156,"y":124,"text":"0","color":"#DC2626"},{"type":"text","x":194,"y":124,"text":"1","color":"#64748B"},{"type":"text","x":234,"y":124,"text":"2","color":"#64748B"}]}}', 'ADMIN', 1, 105, 1, NULL, 0 FROM DUAL
