SELECT 'g7', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '某商品成本为 ${{a}}$ 元，按成本提高 $50\\%$ 标价，再打 $8$ 折销售，实际每件盈利（  ）元', '[]', '{"index":0}', '标价 $1.5\\times {{a}}$，折后售价 $1.5\\times 0.8\\times {{a}} = 1.2\\times {{a}}$，盈利 $0.2\\times {{a}} = {{a*0.2}}$（元）。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"a":[100,300]},"stemTpl":"某商品成本为 ${{a}}$ 元，按成本提高 $50\\\\%$ 标价，再打 $8$ 折销售，实际每件盈利（  ）元","ansExpr":"a * 0.2","wrongExprs":["a * 0.3","a * 0.1","a * 0.25"]}', 4, '["利润率模型","TASK-20261122-002"]', NULL, 'ADMIN', 1, 103, 1, NULL, 0 FROM DUAL
WHERE @ch_id IS NOT NULL AND @gt_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM edu_question WHERE gate_id = @gt_id AND deleted = 0 AND sort_order = 103 AND JSON_CONTAINS(tags_json, '"TASK-20261122-002"'));
