SELECT 'g7', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '点 $P(x, y)$ 满足 $xy < 0$，$x + y > 0$ 且 $|x| < |y|$，则点 $P$ 在（  ）', '["第二象限","第一象限","第三象限","第四象限"]', '{"index":0}', '$xy < 0$ 说明异号，又 $x+y > 0$ 且 $|x| < |y|$，故 $y > 0$、$x < 0$，即第二象限。', NULL, NULL, 4, '["象限符号推理","TASK-20261122-002"]', '{"diagram":{"title":"平面直角坐标系","width":320,"height":210,"primitives":[{"type":"arrow","x1":26,"y1":108,"x2":294,"y2":108,"color":"#64748B"},{"type":"arrow","x1":160,"y1":194,"x2":160,"y2":18,"color":"#64748B"},{"type":"text","x":284,"y":114,"text":"x","color":"#64748B"},{"type":"text","x":167,"y":16,"text":"y","color":"#64748B"},{"type":"text","x":147,"y":113,"text":"O","color":"#64748B"},{"type":"text","x":236,"y":44,"text":"第一象限 (+,+)","color":"#64748B"},{"type":"text","x":34,"y":44,"text":"第二象限 (-,+)","color":"#64748B"},{"type":"text","x":34,"y":164,"text":"第三象限 (-,-)","color":"#64748B"},{"type":"text","x":236,"y":164,"text":"第四象限 (+,-)","color":"#64748B"}]}}', 'ADMIN', 1, 101, 1, NULL, 0 FROM DUAL
WHERE @ch_id IS NOT NULL AND @gt_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM edu_question WHERE gate_id = @gt_id AND deleted = 0 AND sort_order = 101 AND JSON_CONTAINS(tags_json, '"TASK-20261122-002"'));
