SELECT 'g7', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '一个质点在第一象限及坐标轴上按 $(0,0)\\to(0,1)\\to(1,1)\\to(1,0)\\to(2,0)\\to(2,2)\\to(0,2)\\dots$ 规律每秒移动 $1$ 个单位，则第 $3$ 秒时所在位置是（  ）', '["$(1, 0)$","$(1, 1)$","$(2, 0)$","$(0, 1)$"]', '{"index":0}', '第 $1$ 秒在 $(0,1)$，第 $2$ 秒在 $(1,1)$，第 $3$ 秒在 $(1,0)$。', NULL, NULL, 4, '["坐标动点规律","TASK-20261122-002"]', '{"diagram":{"title":"平面直角坐标系","width":320,"height":210,"primitives":[{"type":"arrow","x1":26,"y1":108,"x2":294,"y2":108,"color":"#64748B"},{"type":"arrow","x1":160,"y1":194,"x2":160,"y2":18,"color":"#64748B"},{"type":"text","x":284,"y":114,"text":"x","color":"#64748B"},{"type":"text","x":167,"y":16,"text":"y","color":"#64748B"},{"type":"text","x":147,"y":113,"text":"O","color":"#64748B"},{"type":"text","x":236,"y":44,"text":"第一象限 (+,+)","color":"#64748B"},{"type":"text","x":34,"y":44,"text":"第二象限 (-,+)","color":"#64748B"},{"type":"text","x":34,"y":164,"text":"第三象限 (-,-)","color":"#64748B"},{"type":"text","x":236,"y":164,"text":"第四象限 (+,-)","color":"#64748B"}]}}', 'ADMIN', 1, 102, 1, NULL, 0 FROM DUAL
WHERE @ch_id IS NOT NULL AND @gt_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM edu_question WHERE gate_id = @gt_id AND deleted = 0 AND sort_order = 102 AND JSON_CONTAINS(tags_json, '"TASK-20261122-002"'));
