INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'g7', @ch_id, @gt_id, 'STATIC', 'ESSAY', '在平面直角坐标系中，已知 $A(0, 4)$、$B(-3, 0)$、$C(5, 0)$。\n(1) 求 $\\triangle ABC$ 的面积；\n(2) 点 $M(t, 2)$ 在第一象限且在直线 $AC$ 右上方，若四边形 $ABMC$ 的面积为 $22$，求 $t$ 的值。', '[]', '{"text":"解：\\n(1) $BC = 5 - (-3) = 8$，高 $OA = 4$，故 $S_{\\\\triangle ABC} = \\\\frac{1}{2} \\\\times 8 \\\\times 4 = 16$。\\n(2) 依题意 $S_{\\\\triangle ACM} = 22 - 16 = 6$。\\n过 $M(t, 2)$ 作 $MH \\\\perp x$ 轴于点 $H(t, 0)$（此时 $t > 5$）。\\n梯形 $OAMH$ 面积为 $\\\\frac{(4 + 2)t}{2} = 3t$，\\n其中 $S_{\\\\triangle OAC} = \\\\frac{1}{2} \\\\times 5 \\\\times 4 = 10$，$S_{\\\\triangle CMH} = \\\\frac{1}{2}(t - 5) \\\\times 2 = t - 5$。\\n所以 $S_{\\\\triangle ACM} = 3t - 10 - (t - 5) = 2t - 5$。\\n令 $2t - 5 = 6$，解得 $t = \\\\frac{11}{2}$（即 $5.5$）。"}', '【得分要点】正确求得 $S_{\\triangle ABC} = 16$ 及 $S_{\\triangle ACM} = 6$，用梯形与直角三角形的面积和差列方程求得 $t = \\frac{11}{2}$。', NULL, NULL, 4, '["割补法综合","含参坐标面积","TASK-20261122-002"]', '{"diagram":{"title":"平面直角坐标系","width":320,"height":210,"primitives":[{"type":"arrow","x1":26,"y1":108,"x2":294,"y2":108,"color":"#64748B"},{"type":"arrow","x1":160,"y1":194,"x2":160,"y2":18,"color":"#64748B"},{"type":"text","x":284,"y":114,"text":"x","color":"#64748B"},{"type":"text","x":167,"y":16,"text":"y","color":"#64748B"},{"type":"text","x":147,"y":113,"text":"O","color":"#64748B"},{"type":"text","x":236,"y":44,"text":"第一象限 (+,+)","color":"#64748B"},{"type":"text","x":34,"y":44,"text":"第二象限 (-,+)","color":"#64748B"},{"type":"text","x":34,"y":164,"text":"第三象限 (-,-)","color":"#64748B"},{"type":"text","x":236,"y":164,"text":"第四象限 (+,-)","color":"#64748B"}]}}', 'ADMIN', 1, 105, 1, NULL, 0 FROM DUAL
WHERE @ch_id IS NOT NULL AND @gt_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM edu_question WHERE gate_id = @gt_id AND deleted = 0 AND sort_order = 105 AND JSON_CONTAINS(tags_json, '"TASK-20261122-002"'));

