SELECT 'g7', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '甲、乙两人在环形跑道上同时同地反向而行，每隔 ${{k}}$ 分钟相遇一次；已知跑道全长 $400$ 米，两人速度和为（  ）米/分', '[]', '{"index":0}', '反向相遇一次路程和为一圈 $400$ 米，故速度和 $= \\frac{400}{ {{k}} }$。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"k":[2,6]},"stemTpl":"甲、乙两人在环形跑道上同时同地反向而行，每隔 ${{k}}$ 分钟相遇一次；已知跑道全长 $400$ 米，两人速度和为（  ）米/分","ansExpr":"400 / k","wrongExprs":["400 * k","200 / k","400 / k + 20"]}', 4, '["环形跑道问题","TASK-20261122-002"]', '{"diagram":{"title":"400 米环形跑道反向相遇","width":320,"height":210,"primitives":[{"type":"circle","cx":160,"cy":108,"r":66,"color":"#1E293B","fillColor":"#38BDF8"},{"type":"circle","cx":160,"cy":108,"r":48,"color":"#64748B","dashed":true},{"type":"point","x":160,"y":42,"label":"起点","color":"#DC2626"},{"type":"arrow","x1":146,"y1":36,"x2":114,"y2":48,"color":"#0284C7"},{"type":"arrow","x1":174,"y1":36,"x2":206,"y2":48,"color":"#059669"},{"type":"text","x":62,"y":44,"text":"甲","color":"#0284C7"},{"type":"text","x":244,"y":44,"text":"乙","color":"#059669"},{"type":"text","x":118,"y":102,"text":"全长 400 米","color":"#1E293B"},{"type":"text","x":106,"y":182,"text":"每 {{k}} 分钟相遇一次","color":"#DC2626"}]}}', 'ADMIN', 1, 104, 1, NULL, 0 FROM DUAL
