INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'g7', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '化简不等式 $3x + {{a}} < 5(x - 1) + 3$ 可得到 $2x - {{a}} > C$，其中常数 $C$ 的值为（  ）', '[]', '{"index":0}', '右边展开为 $5x - 2$，移项得 $3x + {{a}} < 5x - 2 \\Rightarrow 2x - {{a}} > 2$，故 $C = 2$。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"a":[4,10]},"stemTpl":"化简不等式 $3x + {{a}} < 5(x - 1) + 3$ 可得到 $2x - {{a}} > C$，其中常数 $C$ 的值为（  ）","ansExpr":"2","wrongExprs":["3","5","1"]}', 4, '["分配盈亏不等式变形","TASK-20261122-002"]', NULL, 'ADMIN', 1, 104, 1, NULL, 0 FROM DUAL
