SELECT 'g8', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '在 $\\triangle ABC$ 中，$\\angle A = {{2*k}}^\\circ$，$\\angle ABC$ 的内角平分线与 $\\angle ACD$（外角）的平分线交于点 $P$，则 $\\angle P$ 的度数为（  ）度', '[]', '{"index":0}', '一内一外角平分线夹角模型：$\\angle P = \\frac{1}{2}\\angle A = {{k}}^\\circ$。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"k":[20,44]},"stemTpl":"在 $\\\\triangle ABC$ 中，$\\\\angle A = {{2*k}}^\\\\circ$，$\\\\angle ABC$ 的内角平分线与 $\\\\angle ACD$（外角）的平分线交于点 $P$，则 $\\\\angle P$ 的度数为（  ）度","ansExpr":"k","wrongExprs":["90 + k","90 - k","180 - k"]}', 3, '["一内一外角平分线模型","TASK-20261122-002"]', '{"diagram":{"title":"一内一外角平分线模型","width":320,"height":210,"primitives":[{"type":"polygon","points":[[118,42],[44,168],[186,168]],"color":"#1E293B","fillColor":"#38BDF8"},{"type":"line","x1":186,"y1":168,"x2":284,"y2":168,"color":"#1E293B"},{"type":"line","x1":44,"y1":168,"x2":256,"y2":84,"color":"#DC2626"},{"type":"line","x1":186,"y1":168,"x2":256,"y2":84,"color":"#DC2626"},{"type":"point","x":256,"y":84,"label":"P","color":"#DC2626"},{"type":"text","x":112,"y":22,"text":"A","color":"#1E293B"},{"type":"text","x":28,"y":172,"text":"B","color":"#1E293B"},{"type":"text","x":182,"y":174,"text":"C","color":"#1E293B"},{"type":"text","x":276,"y":174,"text":"D","color":"#1E293B"}]}}', 'ADMIN', 1, 103, 1, NULL, 0 FROM DUAL
