SELECT 'g8', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '一个凸 ${{n}}$ 边形的所有对角线总条数为（  ）条', '[]', '{"index":0}', '对角线总条数公式 $\\frac{n(n - 3)}{2} = \\frac{ {{n}}({{n}}-3)}{2} = {{n*(n-3)/2}}$。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"n":[6,12]},"stemTpl":"一个凸 ${{n}}$ 边形的所有对角线总条数为（  ）条","ansExpr":"n * (n - 3) / 2","wrongExprs":["n - 3","n * (n - 1) / 2","n * (n - 3)"]}', 4, '["对角线总条数","TASK-20261122-002"]', '{"diagram":{"title":"凸 {{n}} 边形对角线示意","width":320,"height":210,"primitives":[{"type":"polygon","points":[[160,26],[232,56],[250,128],[202,180],[118,180],[70,128],[88,56]],"color":"#1E293B","fillColor":"#38BDF8"},{"type":"line","x1":160,"y1":26,"x2":250,"y2":128,"color":"#DC2626","dashed":true},{"type":"line","x1":160,"y1":26,"x2":202,"y2":180,"color":"#DC2626","dashed":true},{"type":"line","x1":160,"y1":26,"x2":118,"y2":180,"color":"#DC2626","dashed":true},{"type":"line","x1":160,"y1":26,"x2":70,"y2":128,"color":"#DC2626","dashed":true},{"type":"point","x":160,"y":26,"label":"A₁","color":"#DC2626"},{"type":"text","x":104,"y":190,"text":"凸 {{n}} 边形对角线总数 = ?","color":"#0284C7"}]}}', 'ADMIN', 1, 104, 1, NULL, 0 FROM DUAL
