SELECT 'g8', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '已知 $\\triangle ABC \\cong \\triangle A\'B\'C\'$，若 $AB = {{a}}$，$BC = {{b}}$，$\\triangle ABC$ 的周长为 ${{a + b + 6}}$，则 $A\'C\'$ 的长为（  ）', '[]', '{"index":0}', '$AC = {{a+b+6}} - {{a}} - {{b}} = 6$，由全等对应边相等得 $A\'C\' = AC = 6$。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"a":[3,8],"b":[4,9]},"stemTpl":"已知 $\\\\triangle ABC \\\\cong \\\\triangle A\'B\'C\'$，若 $AB = {{a}}$，$BC = {{b}}$，$\\\\triangle ABC$ 的周长为 ${{a + b + 6}}$，则 $A\'C\'$ 的长为（  ）","ansExpr":"6","wrongExprs":["a + b","a + b + 2","5"]}', 1, '["全等对应边","TASK-20261122-002"]', '{"diagram":{"title":"全等三角形 △ABC ≅ △DEF","width":320,"height":210,"primitives":[{"type":"polygon","points":[[84,42],[32,164],[142,164]],"color":"#1E293B","fillColor":"#38BDF8"},{"type":"polygon","points":[[228,42],[176,164],[286,164]],"color":"#0284C7","fillColor":"#34D399"},{"type":"text","x":78,"y":22,"text":"A","color":"#1E293B"},{"type":"text","x":18,"y":166,"text":"B","color":"#1E293B"},{"type":"text","x":144,"y":166,"text":"C","color":"#1E293B"},{"type":"text","x":222,"y":22,"text":"D","color":"#0284C7"},{"type":"text","x":164,"y":166,"text":"E","color":"#0284C7"},{"type":"text","x":288,"y":166,"text":"F","color":"#0284C7"},{"type":"text","x":148,"y":102,"text":"≅","color":"#DC2626"}]}}', 'ADMIN', 1, 103, 1, NULL, 0 FROM DUAL
