SELECT 'g8', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '工人师傅常用角尺平分一个任意角：在 $\\angle AOB$ 的两边上分别取 $OM = ON$，移动角尺使两边刻度重合于 $C$，则 $OC$ 平分 $\\angle AOB$，其依据是（  ）', '["$SSS$","$SAS$","$ASA$","$HL$"]', '{"index":0}', '$OM=ON$、$CM=CN$、公共边 $OC=OC$，由 $SSS$ 判定 $\\triangle OMC \\cong \\triangle ONC$。', NULL, NULL, 3, '["尺规/生活全等应用","TASK-20261122-002"]', '{"diagram":{"title":"工人用角尺平分 ∠AOB","width":320,"height":210,"primitives":[{"type":"arrow","x1":48,"y1":166,"x2":280,"y2":166,"color":"#1E293B"},{"type":"arrow","x1":48,"y1":166,"x2":224,"y2":34,"color":"#1E293B"},{"type":"arrow","x1":48,"y1":166,"x2":264,"y2":96,"color":"#DC2626","dashed":true},{"type":"line","x1":146,"y1":92,"x2":192,"y2":119,"color":"#0284C7"},{"type":"line","x1":170,"y1":166,"x2":192,"y2":119,"color":"#0284C7"},{"type":"point","x":48,"y":166,"color":"#1E293B"},{"type":"point","x":146,"y":92,"label":"M","color":"#0284C7"},{"type":"point","x":170,"y":166,"label":"N","color":"#0284C7"},{"type":"point","x":192,"y":119,"label":"C","color":"#DC2626"},{"type":"text","x":32,"y":168,"text":"O","color":"#1E293B"},{"type":"text","x":228,"y":22,"text":"A","color":"#1E293B"},{"type":"text","x":282,"y":168,"text":"B","color":"#1E293B"},{"type":"text","x":20,"y":24,"text":"OM = ON, CM = CN","color":"#64748B"}]}}', 'ADMIN', 1, 102, 1, NULL, 0 FROM DUAL
