INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'g8', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '如图（手拉手模型）：$\\triangle ABC$ 和 $\\triangle ADE$ 都是等腰直角三角形（$\\angle BAC = \\angle DAE = 90^\\circ$），连接 $BD$、$CE$，下列结论不一定成立的是（  ）', '["$BD \\\\parallel CE$","$BD = CE$","$BD \\\\perp CE$","$\\\\triangle ABD \\\\cong \\\\triangle ACE$"]', '{"index":0}', '由 $SAS$ 易证 $\\triangle ABD \\cong \\triangle ACE$，可得 $BD = CE$ 且旋转 $90^\\circ$ 得 $BD \\perp CE$，而非平行。', NULL, NULL, 4, '["手拉手模型","TASK-20261122-002"]', '{"diagram":{"title":"手拉手模型（等腰直角三角形）","width":320,"height":210,"primitives":[{"type":"polygon","points":[[138,114],[52,164],[88,28]],"color":"#1E293B","fillColor":"#38BDF8"},{"type":"polygon","points":[[138,114],[220,66],[268,148]],"color":"#0284C7","fillColor":"#34D399"},{"type":"rightAngle","vx":138,"vy":114,"ax":52,"ay":164,"bx":88,"by":28,"size":11,"color":"#1E293B"},{"type":"rightAngle","vx":138,"vy":114,"ax":220,"ay":66,"bx":268,"by":148,"size":11,"color":"#0284C7"},{"type":"line","x1":52,"y1":164,"x2":220,"y2":66,"color":"#DC2626","dashed":true},{"type":"line","x1":88,"y1":28,"x2":268,"y2":148,"color":"#D97706","dashed":true},{"type":"point","x":138,"y":114,"color":"#1E293B"},{"type":"point","x":52,"y":164,"color":"#1E293B"},{"type":"point","x":88,"y":28,"color":"#1E293B"},{"type":"point","x":220,"y":66,"color":"#0284C7"},{"type":"point","x":268,"y":148,"color":"#0284C7"},{"type":"text","x":132,"y":126,"text":"A","color":"#1E293B"},{"type":"text","x":36,"y":168,"text":"B","color":"#1E293B"},{"type":"text","x":78,"y":10,"text":"C","color":"#1E293B"},{"type":"text","x":222,"y":48,"text":"D","color":"#0284C7"},{"type":"text","x":272,"y":146,"text":"E","color":"#0284C7"}]}}', 'ADMIN', 1, 101, 1, NULL, 0 FROM DUAL
