SELECT 'g8', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '在 $\\text{Rt}\\triangle ABC$ 中，$\\angle C = 90^\\circ$，$AC = 6$，$BC = 8$，则斜边 $AB$ 上的高 $CD$ 等于（  ）', '["$4.8$","$5$","$2.4$","$4$"]', '{"index":0}', '等面积法：$rac{1}{2}AC\\cdot BC = \\frac{1}{2}AB\\cdot CD \\Rightarrow 6 \\times 8 = 10 \\cdot CD \\Rightarrow CD = 4.8$。', NULL, NULL, 3, '["等面积法求斜边高","TASK-20261122-002"]', '{"diagram":{"title":"直角三角形 Rt△ABC","width":320,"height":210,"primitives":[{"type":"polygon","points":[[76,168],[76,44],[254,168]],"color":"#1E293B","fillColor":"#38BDF8"},{"type":"rightAngle","vx":76,"vy":168,"ax":76,"ay":44,"bx":254,"by":168,"size":12,"color":"#DC2626"},{"type":"text","x":68,"y":24,"text":"A","color":"#1E293B"},{"type":"text","x":258,"y":166,"text":"B","color":"#1E293B"},{"type":"text","x":58,"y":172,"text":"C","color":"#1E293B"},{"type":"text","x":56,"y":104,"text":"b","color":"#0284C7"},{"type":"text","x":158,"y":176,"text":"a","color":"#0284C7"},{"type":"text","x":172,"y":90,"text":"c","color":"#DC2626"}]}}', 'ADMIN', 1, 102, 1, NULL, 0 FROM DUAL
WHERE @ch_id IS NOT NULL AND @gt_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM edu_question WHERE gate_id = @gt_id AND deleted = 0 AND sort_order = 102 AND JSON_CONTAINS(tags_json, '"TASK-20261122-002"'));
