INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'g8', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '如图（赵爽弦图）：由 $4$ 个全等的直角三角形与中间一个小正方形拼成一个大正方形，若大正方形面积为 $25$，小正方形面积为 $1$，直角三角形较短直角边为 $a$、较长直角边为 $b$，则 $(a + b)^2$ 的值为（  ）', '["$49$","$36$","$25$","$50$"]', '{"index":0}', '大正方形面积 $a^2+b^2=25$，每个直角三角形面积 $= \\frac{25-1}{4} = 6 \\Rightarrow \\frac{1}{2}ab = 6 \\Rightarrow 2ab = 24$，故 $(a+b)^2 = a^2+b^2+2ab = 25+24 = 49$。', NULL, NULL, 4, '["赵爽弦图","TASK-20261122-002"]', '{"diagram":{"title":"赵爽弦图示意图","width":320,"height":210,"primitives":[{"type":"polygon","points":[[84,22],[236,22],[236,174],[84,174]],"color":"#1E293B","fillColor":"#38BDF8"},{"type":"polygon","points":[[144,82],[176,82],[176,114],[144,114]],"color":"#DC2626","fillColor":"#FBBF24"},{"type":"line","x1":84,"y1":22,"x2":176,"y2":82,"color":"#1E293B"},{"type":"line","x1":236,"y1":22,"x2":176,"y2":114,"color":"#1E293B"},{"type":"line","x1":236,"y1":174,"x2":144,"y2":114,"color":"#1E293B"},{"type":"line","x1":84,"y1":174,"x2":144,"y2":82,"color":"#1E293B"},{"type":"text","x":148,"y":92,"text":"S=1","color":"#DC2626"},{"type":"text","x":112,"y":38,"text":"a","color":"#0284C7"},{"type":"text","x":204,"y":52,"text":"b","color":"#0284C7"},{"type":"text","x":98,"y":182,"text":"大正方形面积 = 25","color":"#64748B"}]}}', 'ADMIN', 1, 101, 1, NULL, 0 FROM DUAL
WHERE @ch_id IS NOT NULL AND @gt_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM edu_question WHERE gate_id = @gt_id AND deleted = 0 AND sort_order = 101 AND JSON_CONTAINS(tags_json, '"TASK-20261122-002"'));
INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'g8', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '在折叠矩形问题中：长方形 $ABCD$ 中 $AB = 8$，$BC = 4$，将矩形沿对角线 $AC$ 折叠，点 $D$ 落在 $D\'$ 处，$AD\'$ 交 $BC$ 于点 $E$，则重叠部分 $\\triangle AEC$ 的面积是（  ）', '["$10$","$12$","$8$","$16$"]', '{"index":0}', '易证 $AE = EC$，设 $CE = x$，则 $BE = 8 - x$。在 $\\text{Rt}\\triangle ABE$ 中 $4^2 + (8-x)^2 = x^2 \\Rightarrow 16 + 64 - 16x = 0 \\Rightarrow x = 5$，故 $S_{\\triangle AEC} = \\frac{1}{2}\\times 5\\times 4 = 10$。', NULL, NULL, 4, '["折叠与勾股方程","TASK-20261122-002"]', '{"diagram":{"title":"直角三角形 Rt△ABC","width":320,"height":210,"primitives":[{"type":"polygon","points":[[76,168],[76,44],[254,168]],"color":"#1E293B","fillColor":"#38BDF8"},{"type":"rightAngle","vx":76,"vy":168,"ax":76,"ay":44,"bx":254,"by":168,"size":12,"color":"#DC2626"},{"type":"text","x":68,"y":24,"text":"A","color":"#1E293B"},{"type":"text","x":258,"y":166,"text":"B","color":"#1E293B"},{"type":"text","x":58,"y":172,"text":"C","color":"#1E293B"},{"type":"text","x":56,"y":104,"text":"b","color":"#0284C7"},{"type":"text","x":158,"y":176,"text":"a","color":"#0284C7"},{"type":"text","x":172,"y":90,"text":"c","color":"#DC2626"}]}}', 'ADMIN', 1, 102, 1, NULL, 0 FROM DUAL
WHERE @ch_id IS NOT NULL AND @gt_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM edu_question WHERE gate_id = @gt_id AND deleted = 0 AND sort_order = 102 AND JSON_CONTAINS(tags_json, '"TASK-20261122-002"'));
INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'g8', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '费马型几何最值：利用勾股构造“将军饮马”——求代数式 $\\sqrt{x^2 + {{a*a}} } + \\sqrt{(8 - x)^2 + {{a*a}} }$ 的最小值的平方等于（  ）', '[]', '{"index":0}', '可视为点 $(x, 0)$ 到 $(0, {{a}})$ 与 $(8, -{{a}})$ 的距离之和，最小值为两点连线长 $\\sqrt{(8-0)^2 + ({{a}} - (-{{a}}))^2} = \\sqrt{64 + 4\\times {{a*a}} }$，其平方为 ${{64 + 4*a*a}}$。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"a":[3,6]},"stemTpl":"费马型几何最值：利用勾股构造“将军饮马”——求代数式 $\\\\sqrt{x^2 + {{a*a}} } + \\\\sqrt{(8 - x)^2 + {{a*a}} }$ 的最小值的平方等于（  ）","ansExpr":"64 + 4 * a * a","wrongExprs":["64 + a * a","64 + 2 * a * a","64"]}', 4, '["数形结合勾股最值","TASK-20261122-002"]', '{"diagram":{"title":"直角三角形 Rt△ABC","width":320,"height":210,"primitives":[{"type":"polygon","points":[[76,168],[76,44],[254,168]],"color":"#1E293B","fillColor":"#38BDF8"},{"type":"rightAngle","vx":76,"vy":168,"ax":76,"ay":44,"bx":254,"by":168,"size":12,"color":"#DC2626"},{"type":"text","x":68,"y":24,"text":"A","color":"#1E293B"},{"type":"text","x":258,"y":166,"text":"B","color":"#1E293B"},{"type":"text","x":58,"y":172,"text":"C","color":"#1E293B"},{"type":"text","x":56,"y":104,"text":"b","color":"#0284C7"},{"type":"text","x":158,"y":176,"text":"a","color":"#0284C7"},{"type":"text","x":172,"y":90,"text":"c","color":"#DC2626"}]}}', 'ADMIN', 1, 103, 1, NULL, 0 FROM DUAL
WHERE @ch_id IS NOT NULL AND @gt_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM edu_question WHERE gate_id = @gt_id AND deleted = 0 AND sort_order = 103 AND JSON_CONTAINS(tags_json, '"TASK-20261122-002"'));
INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'g8', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '一个长为 $8$、宽为 $6$ 的矩形，若将它的长和宽同时扩大到原来的 ${{b}}$ 倍，则新矩形的对角线长为（  ）', '[]', '{"index":0}', '长宽同扩 ${{b}}$ 倍，原对角线为 $\\sqrt{8^2+6^2}=10$，新对角线等比例扩大 ${{b}}$ 倍，为 $10\\times {{b}} = {{10*b}}$。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"b":[2,7]},"stemTpl":"一个长为 $8$、宽为 $6$ 的矩形，若将它的长和宽同时扩大到原来的 ${{b}}$ 倍，则新矩形的对角线长为（  ）","ansExpr":"10 * b","wrongExprs":["10 + b","5 * b","14 * b"]}', 4, '["勾股比例缩放","TASK-20261122-002"]', '{"diagram":{"title":"矩形按 {{b}} 倍缩放对角线示意","width":320,"height":210,"primitives":[{"type":"polygon","points":[[68,46],[252,46],[252,164],[68,164]],"color":"#1E293B","fillColor":"#38BDF8"},{"type":"line","x1":68,"y1":164,"x2":252,"y2":46,"color":"#DC2626"},{"type":"rightAngle","vx":68,"vy":164,"ax":68,"ay":46,"bx":252,"by":164,"size":11,"color":"#0284C7"},{"type":"text","x":136,"y":172,"text":"长 = 8 × {{b}}","color":"#0284C7"},{"type":"text","x":14,"y":98,"text":"宽 6×{{b}}","color":"#0284C7"},{"type":"text","x":146,"y":86,"text":"d = ?","color":"#DC2626"}]}}', 'ADMIN', 1, 104, 1, NULL, 0 FROM DUAL
WHERE @ch_id IS NOT NULL AND @gt_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM edu_question WHERE gate_id = @gt_id AND deleted = 0 AND sort_order = 104 AND JSON_CONTAINS(tags_json, '"TASK-20261122-002"'));
INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'g8', @ch_id, @gt_id, 'STATIC', 'ESSAY', '如图，在四边形 $ABCD$ 中，$\\angle B = 90^\\circ$，$AB = 3$，$BC = 4$，$CD = 12$，$AD = 13$，试求四边形 $ABCD$ 的面积。', '[]', '{"text":"解：\\n连接 $AC$。\\n在 $\\\\text{Rt}\\\\triangle ABC$ 中，$\\\\angle B = 90^\\\\circ$，$AB = 3$，$BC = 4$，\\n由勾股定理得 $AC = \\\\sqrt{AB^2 + BC^2} = \\\\sqrt{3^2 + 4^2} = 5$。\\n$S_{\\\\triangle ABC} = \\\\frac{1}{2} \\\\times 3 \\\\times 4 = 6$。\\n在 $\\\\triangle ACD$ 中，$AC^2 + CD^2 = 5^2 + 12^2 = 25 + 144 = 169 = 13^2 = AD^2$，\\n所以 $\\\\triangle ACD$ 是直角三角形，且 $\\\\angle ACD = 90^\\\\circ$。\\n故 $S_{\\\\triangle ACD} = \\\\frac{1}{2} \\\\times 5 \\\\times 12 = 30$。\\n因此，四边形 $ABCD$ 的面积 $= 6 + 30 = 36$。"}', '【得分要点】作辅助线 $AC$ 将四边形分成两个三角形，先用勾股定理求 $AC=5$，再用勾股逆定理证 $\\angle ACD=90^\\circ$ 后求总面积 $36$。', NULL, NULL, 4, '["勾股定理与逆定理联用","手写解答","TASK-20261122-002"]', '{"diagram":{"title":"四边形 ABCD (∠B = 90°)","width":320,"height":210,"primitives":[{"type":"polygon","points":[[68,168],[68,102],[254,42],[156,168]],"color":"#1E293B","fillColor":"#38BDF8"},{"type":"line","x1":68,"y1":102,"x2":156,"y2":168,"color":"#DC2626","dashed":true},{"type":"rightAngle","vx":68,"vy":168,"ax":68,"ay":102,"bx":156,"by":168,"size":11,"color":"#0284C7"},{"type":"point","x":68,"y":102,"color":"#1E293B"},{"type":"point","x":68,"y":168,"color":"#1E293B"},{"type":"point","x":156,"y":168,"color":"#1E293B"},{"type":"point","x":254,"y":42,"color":"#1E293B"},{"type":"text","x":50,"y":94,"text":"A","color":"#1E293B"},{"type":"text","x":50,"y":170,"text":"B","color":"#1E293B"},{"type":"text","x":154,"y":174,"text":"C","color":"#1E293B"},{"type":"text","x":258,"y":34,"text":"D","color":"#1E293B"},{"type":"text","x":44,"y":130,"text":"3","color":"#0284C7"},{"type":"text","x":106,"y":174,"text":"4","color":"#0284C7"},{"type":"text","x":210,"y":112,"text":"12","color":"#0284C7"},{"type":"text","x":152,"y":54,"text":"13","color":"#0284C7"}]}}', 'ADMIN', 1, 105, 1, NULL, 0 FROM DUAL
WHERE @ch_id IS NOT NULL AND @gt_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM edu_question WHERE gate_id = @gt_id AND deleted = 0 AND sort_order = 105 AND JSON_CONTAINS(tags_json, '"TASK-20261122-002"'));

