INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'g8', @ch_id, @gt_id, 'STATIC', 'ESSAY', '已知一次函数 $y = kx + b$ 的图象经过点 $A(2, 5)$ 和 $B(-1, -1)$。\n(1) 求该一次函数的解析式；\n(2) 求直线与两坐标轴所围成的三角形面积；\n(3) 直接写出当 $y > 0$ 时自变量 $x$ 的取值范围。', '[]', '{"text":"解：\\n(1) 把 $A(2, 5)$ 和 $B(-1, -1)$ 代入 $y = kx + b$，得：\\n$\\\\begin{cases} 2k + b = 5 \\\\\\\\ -k + b = -1 \\\\end{cases}$\\n两式相减得 $3k = 6 \\\\Rightarrow k = 2$，代入得 $b = 1$。\\n所以一次函数解析式为 $y = 2x + 1$。\\n(2) 令 $x = 0$ 得 $y = 1$；令 $y = 0$ 得 $x = -\\\\frac{1}{2}$。\\n三角形面积 $= \\\\frac{1}{2} \\\\times \\\\left|-\\\\frac{1}{2}\\\\right| \\\\times 1 = \\\\frac{1}{4}$。\\n(3) 由 $2x + 1 > 0$ 得 $x > -\\\\frac{1}{2}$。"}', '【得分要点】正确用待定系数法求得 $y=2x+1$，面积取绝对值得到 $\\frac{1}{4}$，不等式解集为 $x > -\\frac{1}{2}$。', NULL, NULL, 3, '["待定系数与函数不等式","手写解答","TASK-20261122-002"]', '{"diagram":{"title":"一次函数 y = kx + b 图象示意","width":320,"height":210,"primitives":[{"type":"arrow","x1":26,"y1":122,"x2":294,"y2":122,"color":"#64748B"},{"type":"arrow","x1":148,"y1":194,"x2":148,"y2":18,"color":"#64748B"},{"type":"text","x":284,"y":128,"text":"x","color":"#64748B"},{"type":"text","x":155,"y":16,"text":"y","color":"#64748B"},{"type":"text","x":135,"y":127,"text":"O","color":"#64748B"},{"type":"line","x1":54,"y1":174,"x2":266,"y2":42,"color":"#0284C7"},{"type":"point","x":148,"y":115,"color":"#DC2626"},{"type":"point","x":136,"y":122,"color":"#059669"},{"type":"text","x":218,"y":42,"text":"y = kx + b","color":"#0284C7"}]}}', 'ADMIN', 1, 104, 1, NULL, 0 FROM DUAL
WHERE @ch_id IS NOT NULL AND @gt_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM edu_question WHERE gate_id = @gt_id AND deleted = 0 AND sort_order = 104 AND JSON_CONTAINS(tags_json, '"TASK-20261122-002"'));

