INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'g8', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '当 $-1 \\le x \\le 3$ 时，一次函数 $y = kx + b$（$k < 0$）的最大值为 $7$、最小值为 $-1$，则 $k + b$ 的值为（  ）', '["$3$","$5$","$7$","$-1$"]', '{"index":0}', '因为 $k < 0$，函数单调递减，所以 $x=-1$ 时 $y=-k+b=7$，$x=3$ 时 $y=3k+b=-1$。两式相减得 $4k = -8 \\Rightarrow k = -2$，代入得 $b = 5$，故 $k+b = 3$。', NULL, NULL, 4, '["区间最值求解析式","TASK-20261122-002"]', '{"diagram":{"title":"一次函数 y = kx + b 图象示意","width":320,"height":210,"primitives":[{"type":"arrow","x1":26,"y1":122,"x2":294,"y2":122,"color":"#64748B"},{"type":"arrow","x1":148,"y1":194,"x2":148,"y2":18,"color":"#64748B"},{"type":"text","x":284,"y":128,"text":"x","color":"#64748B"},{"type":"text","x":155,"y":16,"text":"y","color":"#64748B"},{"type":"text","x":135,"y":127,"text":"O","color":"#64748B"},{"type":"line","x1":54,"y1":174,"x2":266,"y2":42,"color":"#0284C7"},{"type":"point","x":148,"y":115,"color":"#DC2626"},{"type":"point","x":136,"y":122,"color":"#059669"},{"type":"text","x":218,"y":42,"text":"y = kx + b","color":"#0284C7"}]}}', 'ADMIN', 1, 101, 1, NULL, 0 FROM DUAL
WHERE @ch_id IS NOT NULL AND @gt_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM edu_question WHERE gate_id = @gt_id AND deleted = 0 AND sort_order = 101 AND JSON_CONTAINS(tags_json, '"TASK-20261122-002"'));
INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'g8', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '已知一次函数 $y = (m - 1)x + m + 2$ 无论 $m$ 取何值都经过一个定点，这个定点的坐标是（  ）', '["$(-1, 3)$","$(1, 3)$","$(-1, -3)$","$(0, 2)$"]', '{"index":0}', '整理成含 $m$ 的式子：$y = m(x + 1) + (2 - x)$，令系数 $x + 1 = 0$ 得 $x = -1$，此时 $y = 2 - (-1) = 3$。', NULL, NULL, 4, '["过定点问题","TASK-20261122-002"]', '{"diagram":{"title":"一次函数 y = kx + b 图象示意","width":320,"height":210,"primitives":[{"type":"arrow","x1":26,"y1":122,"x2":294,"y2":122,"color":"#64748B"},{"type":"arrow","x1":148,"y1":194,"x2":148,"y2":18,"color":"#64748B"},{"type":"text","x":284,"y":128,"text":"x","color":"#64748B"},{"type":"text","x":155,"y":16,"text":"y","color":"#64748B"},{"type":"text","x":135,"y":127,"text":"O","color":"#64748B"},{"type":"line","x1":54,"y1":174,"x2":266,"y2":42,"color":"#0284C7"},{"type":"point","x":148,"y":115,"color":"#DC2626"},{"type":"point","x":136,"y":122,"color":"#059669"},{"type":"text","x":218,"y":42,"text":"y = kx + b","color":"#0284C7"}]}}', 'ADMIN', 1, 102, 1, NULL, 0 FROM DUAL
