SELECT 'g9', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '用一段长为 ${{2*a}}$ 米的篱笆围成一个一面靠墙（墙足够长）的矩形菜园，则能围成的菜园最大面积是（  ）平方米', '[]', '{"index":0}', '设垂直于墙的宽为 $x$，平行于墙的长为 $({{2*a}} - 2x)$，面积 $S = x({{2*a}} - 2x) = -2(x - \\frac{ {{a}} }{2})^2 + \\frac{ {{a}}^2}{2}$，最大面积为 $\\frac{ {{a*a}} }{2}$。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"a":[4,10]},"stemTpl":"用一段长为 ${{2*a}}$ 米的篱笆围成一个一面靠墙（墙足够长）的矩形菜园，则能围成的菜园最大面积是（  ）平方米","ansExpr":"a * a / 2","wrongExprs":["a * a","a * a / 4","2 * a * a"]}', 3, '["靠墙矩形面积最值","TASK-20261122-002"]', '{"diagram":{"title":"一面靠墙的矩形菜园示意图","width":320,"height":210,"primitives":[{"type":"line","x1":34,"y1":48,"x2":286,"y2":48,"color":"#1E293B"},{"type":"line","x1":48,"y1":38,"x2":60,"y2":48,"color":"#64748B"},{"type":"line","x1":88,"y1":38,"x2":100,"y2":48,"color":"#64748B"},{"type":"line","x1":128,"y1":38,"x2":140,"y2":48,"color":"#64748B"},{"type":"line","x1":168,"y1":38,"x2":180,"y2":48,"color":"#64748B"},{"type":"line","x1":208,"y1":38,"x2":220,"y2":48,"color":"#64748B"},{"type":"line","x1":248,"y1":38,"x2":260,"y2":48,"color":"#64748B"},{"type":"text","x":136,"y":20,"text":"墙（足够长）","color":"#64748B"},{"type":"polygon","points":[[76,48],[244,48],[244,152],[76,152]],"color":"#059669","fillColor":"#34D399"},{"type":"line","x1":76,"y1":48,"x2":76,"y2":152,"color":"#DC2626"},{"type":"line","x1":76,"y1":152,"x2":244,"y2":152,"color":"#DC2626"},{"type":"line","x1":244,"y1":152,"x2":244,"y2":48,"color":"#DC2626"},{"type":"text","x":48,"y":96,"text":"x","color":"#DC2626"},{"type":"text","x":252,"y":96,"text":"x","color":"#DC2626"},{"type":"text","x":116,"y":162,"text":"篱笆总长 = {{2*a}} 米","color":"#DC2626"}]}}', 'ADMIN', 1, 103, 1, NULL, 0 FROM DUAL
