SELECT 'g9', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '圆锥的底面半径为 ${{r}}$，母线长为 ${{2*r}}$，将该圆锥侧面沿一条母线剪开铺平得到一个扇形，这个扇形的圆心角为（  ）度', '[]', '{"index":0}', '圆心角 $\\theta = \\frac{r}{l} \\times 360^\\circ = \\frac{ {{r}} }{ {{2*r}} } \\times 360^\\circ = 180^\\circ$。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"r":[4,10]},"stemTpl":"圆锥的底面半径为 ${{r}}$，母线长为 ${{2*r}}$，将该圆锥侧面沿一条母线剪开铺平得到一个扇形，这个扇形的圆心角为（  ）度","ansExpr":"180","wrongExprs":["90","120","270"]}', 4, '["圆锥侧面展开角","TASK-20261122-002"]', '{"diagram":{"title":"圆心角与圆周角关系","width":320,"height":210,"primitives":[{"type":"circle","cx":160,"cy":108,"r":72,"color":"#1E293B","fillColor":"#38BDF8"},{"type":"line","x1":160,"y1":108,"x2":102,"y2":150,"color":"#DC2626"},{"type":"line","x1":160,"y1":108,"x2":218,"y2":150,"color":"#DC2626"},{"type":"line","x1":146,"y1":37,"x2":102,"y2":150,"color":"#0284C7"},{"type":"line","x1":146,"y1":37,"x2":218,"y2":150,"color":"#0284C7"},{"type":"point","x":160,"y":108,"label":"O","color":"#DC2626"},{"type":"point","x":146,"y":37,"color":"#0284C7"},{"type":"text","x":86,"y":154,"text":"A","color":"#1E293B"},{"type":"text","x":222,"y":154,"text":"B","color":"#1E293B"},{"type":"text","x":142,"y":18,"text":"C","color":"#0284C7"}]}}', 'ADMIN', 1, 103, 1, NULL, 0 FROM DUAL
WHERE @ch_id IS NOT NULL AND @gt_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM edu_question WHERE gate_id = @gt_id AND deleted = 0 AND sort_order = 103 AND JSON_CONTAINS(tags_json, '"TASK-20261122-002"'));
