SELECT 'g9', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '一个圆形转盘阴影区域与白色区域组成，其中阴影圆心角占 $90^\\circ$，若再在另一盒子里随机取标号 $1\\sim {{total}}$ 的卡片中抽取一张，抽到编号不超过 ${{red}}$ 的概率是（  ）', '[]', '{"index":0}', '共 ${{total}}$ 张等可能卡片，不超过 ${{red}}$ 的有 ${{red}}$ 张，故概率为 $\\frac{ {{red}} }{ {{total}} }$。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"total":[20,40],"red":[4,8]},"stemTpl":"一个圆形转盘阴影区域与白色区域组成，其中阴影圆心角占 $90^\\\\circ$，若再在另一盒子里随机取标号 $1\\\\sim {{total}}$ 的卡片中抽取一张，抽到编号不超过 ${{red}}$ 的概率是（  ）","ansExpr":"frac(red, total)","wrongExprs":["frac(red + 1, total)","frac(total - red, total)","frac(1, total)"]}', 3, '["古典概率计算","TASK-20261122-002"]', '{"diagram":{"title":"圆形转盘（阴影圆心角 90°）","width":320,"height":210,"primitives":[{"type":"circle","cx":160,"cy":108,"r":70,"color":"#1E293B"},{"type":"arc","cx":160,"cy":108,"r":70,"startAngle":-90,"sweepAngle":90,"color":"#DC2626","fillColor":"#FBBF24"},{"type":"line","x1":160,"y1":108,"x2":160,"y2":38,"color":"#1E293B"},{"type":"line","x1":160,"y1":108,"x2":230,"y2":108,"color":"#1E293B"},{"type":"rightAngle","vx":160,"vy":108,"ax":160,"ay":38,"bx":230,"by":108,"size":11,"color":"#DC2626"},{"type":"point","x":160,"y":108,"color":"#1E293B"},{"type":"text","x":176,"y":70,"text":"90°阴影","color":"#DC2626"},{"type":"text","x":98,"y":132,"text":"白色区域","color":"#64748B"}]}}', 'ADMIN', 1, 103, 1, NULL, 0 FROM DUAL
