INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'g9', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '如图（几何概型）：一只蚂蚁在由边长为 $1$ 的小正方形组成的 $4\\times 4$ 网格大正方形内随机爬行，在大正方形内画一个内切圆（半径为 $2$），蚂蚁停留在圆内的概率为（  ）', '["$\\\\frac{\\\\pi}{4}$","$\\\\frac{\\\\pi}{2}$","$\\\\frac{1}{4}$","$\\\\frac{\\\\pi}{16}$"]', '{"index":0}', '大正方形面积 $= 4^2 = 16$，内切圆面积 $= \\pi \\times 2^2 = 4\\pi$，故停在圆内的概率为 $\\frac{4\\pi}{16} = \\frac{\\pi}{4}$。', NULL, NULL, 4, '["几何概率面积比","TASK-20261122-002"]', '{"diagram":{"title":"4×4 网格与内切圆几何概型","width":320,"height":210,"primitives":[{"type":"polygon","points":[[92,32],[236,32],[236,176],[92,176]],"color":"#1E293B"},{"type":"line","x1":128,"y1":32,"x2":128,"y2":176,"color":"#64748B","dashed":true},{"type":"line","x1":92,"y1":68,"x2":236,"y2":68,"color":"#64748B","dashed":true},{"type":"line","x1":164,"y1":32,"x2":164,"y2":176,"color":"#64748B","dashed":true},{"type":"line","x1":92,"y1":104,"x2":236,"y2":104,"color":"#64748B","dashed":true},{"type":"line","x1":200,"y1":32,"x2":200,"y2":176,"color":"#64748B","dashed":true},{"type":"line","x1":92,"y1":140,"x2":236,"y2":140,"color":"#64748B","dashed":true},{"type":"circle","cx":164,"cy":104,"r":72,"color":"#DC2626","fillColor":"#38BDF8"},{"type":"point","x":164,"y":104,"label":"O","color":"#DC2626"},{"type":"text","x":246,"y":98,"text":"r = 2","color":"#DC2626"}]}}', 'ADMIN', 1, 101, 1, NULL, 0 FROM DUAL
