INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'g9', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '从数字 $-2, -1, 1, 2$ 中任取一个数作为点 $P(a, b)$ 的横坐标 $a$，再从剩下三个数中任取一个作为纵坐标 $b$，则点 $P$ 落在反比例函数 $y = \\frac{2}{x}$ 图象上的概率是（  ）', '["$\\\\frac{1}{3}$","$\\\\frac{1}{6}$","$\\\\frac{1}{4}$","$\\\\frac{1}{12}$"]', '{"index":0}', '共有 $4\\times 3 = 12$ 个有序点 $(a, b)$，满足 $ab = 2$ 的点有 $(1, 2)$、$(2, 1)$、$(-1, -2)$、$(-2, -1)$ 共 $4$ 个点，故概率为 $\\frac{4}{12} = \\frac{1}{3}$。', NULL, NULL, 4, '["概率与函数综合","TASK-20261122-002"]', '{"diagram":{"title":"反比例函数 y = 2/x 与格点示意","width":320,"height":210,"primitives":[{"type":"arrow","x1":28,"y1":108,"x2":292,"y2":108,"color":"#64748B"},{"type":"arrow","x1":160,"y1":196,"x2":160,"y2":16,"color":"#64748B"},{"type":"text","x":282,"y":114,"text":"x","color":"#64748B"},{"type":"text","x":167,"y":14,"text":"y","color":"#64748B"},{"type":"text","x":147,"y":113,"text":"O","color":"#64748B"},{"type":"polyline","points":[[183.8,10.9],[187.3,23.4],[190.9,33.1],[194.4,40.8],[198,47.1],[201.5,52.3],[205.1,56.7],[208.6,60.4],[212.1,63.7],[215.7,66.5],[219.2,69],[222.8,71.2],[226.3,73.1],[229.8,74.9],[233.4,76.5],[236.9,77.9],[240.5,79.3],[244,80.5],[247.6,81.6],[251.1,82.6],[254.6,83.6],[258.2,84.5],[261.7,85.3],[265.3,86],[268.8,86.8]],"color":"#0284C7"},{"type":"polyline","points":[[51.2,129.3],[54.7,130],[58.3,130.7],[61.8,131.5],[65.4,132.4],[68.9,133.4],[72.4,134.4],[76,135.5],[79.5,136.7],[83.1,138.1],[86.6,139.5],[90.2,141.1],[93.7,142.9],[97.2,144.8],[100.8,147],[104.3,149.5],[107.9,152.3],[111.4,155.6],[115,159.3],[118.5,163.7],[122,168.9],[125.6,175.2],[129.1,182.9],[132.7,192.6]],"color":"#0284C7"},{"type":"point","x":194,"y":40,"label":"(1,2)","color":"#DC2626"},{"type":"point","x":228,"y":74,"label":"(2,1)","color":"#DC2626"},{"type":"point","x":126,"y":176,"label":"(-1,-2)","color":"#DC2626"},{"type":"point","x":92,"y":142,"label":"(-2,-1)","color":"#DC2626"},{"type":"text","x":226,"y":36,"text":"y = 2/x","color":"#0284C7"}]}}', 'ADMIN', 1, 102, 1, NULL, 0 FROM DUAL
