INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'g9', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '在一个暗盒中装有红球 $3$ 个、白球 ${{k}}$ 个及黑球若干个（质地大小均相同）。若经过大量重复摸球试验发现摸到红球的频率稳定在 $0.15$，估计暗盒中球的总数大约有（  ）个', '[]', '{"index":0}', '红球数量除以红球概率估算总数：$3 \\div 0.15 = 20$（个）。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"k":[2,6]},"stemTpl":"在一个暗盒中装有红球 $3$ 个、白球 ${{k}}$ 个及黑球若干个（质地大小均相同）。若经过大量重复摸球试验发现摸到红球的频率稳定在 $0.15$，估计暗盒中球的总数大约有（  ）个","ansExpr":"20","wrongExprs":["15","30","45"]}', 4, '["由频率反估总数","TASK-20261122-002"]', NULL, 'ADMIN', 1, 104, 1, NULL, 0 FROM DUAL
WHERE @ch_id IS NOT NULL AND @gt_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM edu_question WHERE gate_id = @gt_id AND deleted = 0 AND sort_order = 104 AND JSON_CONTAINS(tags_json, '"TASK-20261122-002"'));
INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'g9', @ch_id, @gt_id, 'STATIC', 'ESSAY', '甲、乙两人玩扑克牌游戏，甲手中持有红桃 $1, 2, 3$（分别计为 $1, 2, 3$ 点），乙手中持有黑桃 $1, 2, 3$（分别计为 $1, 2, 3$ 点）。两人各自随机出一张牌比大小，点数大者获胜，若点数相同则为平局。\n(1) 列出两人出牌的所有可能结果，并求平局的概率；\n(2) 规定：若两人点数之和为奇数则甲得 $1$ 分，点数之和为偶数则乙得 $1$ 分，请问这个规则公平吗？说明理由。', '[]', '{"text":"解：\\n(1) 用列表（或树状图）共产生 $3 \\\\times 3 = 9$ 种等可能结果：\\n$(1,1), (1,2), (1,3), (2,1), (2,2), (2,3), (3,1), (3,2), (3,3)$。\\n平局的结果有 $(1,1), (2,2), (3,3)$ 共 $3$ 种，\\n所以 $P(\\\\text{平局}) = \\\\frac{3}{9} = \\\\frac{1}{3}$。\\n(2) 这个规则不公平。\\n理由：点数之和为奇数的结果有 $(1,2), (2,1), (2,3), (3,2)$ 共 $4$ 种，故 $P(\\\\text{甲得分}) = \\\\frac{4}{9}$；\\n点数之和为偶数的结果有 $(1,1), (1,3), (2,2), (3,1), (3,3)$ 共 $5$ 种，故 $P(\\\\text{乙得分}) = \\\\frac{5}{9}$。\\n因为 $\\\\frac{4}{9} \\\\neq \\\\frac{5}{9}$，两人获胜概率不相等，所以游戏规则不公平。"}', '【得分要点】(1) 列举全部 $9$ 种结果算出平局概率 $\\frac{1}{3}$；(2) 分别求出和为奇偶的概率 $\\frac{4}{9}$ 与 $\\frac{5}{9}$，指出不相等故不公平。', NULL, NULL, 4, '["游戏公平性评估","手写解答","TASK-20261122-002"]', NULL, 'ADMIN', 1, 105, 1, NULL, 0 FROM DUAL
WHERE @ch_id IS NOT NULL AND @gt_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM edu_question WHERE gate_id = @gt_id AND deleted = 0 AND sort_order = 105 AND JSON_CONTAINS(tags_json, '"TASK-20261122-002"'));

