SELECT 'g9', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '在 $\\text{Rt}\\triangle ABC$ 中，$\\angle C = 90^\\circ$，$\\mathrm{sin}\\,A = \\frac{1}{2}$，若 $BC = {{a}}$，则斜边 $AB$ 的长是（  ）', '[]', '{"index":0}', '$\\frac{BC}{AB} = \\frac{1}{2} \\Rightarrow AB = 2\\times {{a}} = {{2*a}}$。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"a":[2,6]},"stemTpl":"在 $\\\\text{Rt}\\\\triangle ABC$ 中，$\\\\angle C = 90^\\\\circ$，$\\\\mathrm{sin}\\\\,A = \\\\frac{1}{2}$，若 $BC = {{a}}$，则斜边 $AB$ 的长是（  ）","ansExpr":"2 * a","wrongExprs":["a","3 * a","4 * a"]}', 1, '["正弦解直角三角形","TASK-20261122-002"]', '{"diagram":{"title":"直角三角形 Rt△ABC","width":320,"height":210,"primitives":[{"type":"polygon","points":[[76,168],[76,44],[254,168]],"color":"#1E293B","fillColor":"#38BDF8"},{"type":"rightAngle","vx":76,"vy":168,"ax":76,"ay":44,"bx":254,"by":168,"size":12,"color":"#DC2626"},{"type":"text","x":68,"y":24,"text":"A","color":"#1E293B"},{"type":"text","x":258,"y":166,"text":"B","color":"#1E293B"},{"type":"text","x":58,"y":172,"text":"C","color":"#1E293B"},{"type":"arc","cx":76,"cy":44,"r":24,"startAngle":34,"sweepAngle":56,"color":"#0284C7"},{"type":"text","x":90,"y":74,"text":"∠A","color":"#0284C7"}]}}', 'ADMIN', 1, 104, 1, NULL, 0 FROM DUAL
