SELECT 'g9', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '在 $\\triangle ABC$ 中，$\\angle C = 90^\\circ$，$AB = {{a}}$，若 $\\mathrm{sin}\\,A = 0.6$，则 $BC$ 等于（  ）', '[]', '{"index":0}', '$BC = AB \\cdot \\mathrm{sin}\\,A = {{a}} \\times 0.6 = {{0.6*a}}$。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"a":[4,10]},"stemTpl":"在 $\\\\triangle ABC$ 中，$\\\\angle C = 90^\\\\circ$，$AB = {{a}}$，若 $\\\\mathrm{sin}\\\\,A = 0.6$，则 $BC$ 等于（  ）","ansExpr":"0.6 * a","wrongExprs":["0.8 * a","0.4 * a","a"]}', 2, '["边角转换","TASK-20261122-002"]', '{"diagram":{"title":"直角三角形 Rt△ABC","width":320,"height":210,"primitives":[{"type":"polygon","points":[[76,168],[76,44],[254,168]],"color":"#1E293B","fillColor":"#38BDF8"},{"type":"rightAngle","vx":76,"vy":168,"ax":76,"ay":44,"bx":254,"by":168,"size":12,"color":"#DC2626"},{"type":"text","x":68,"y":24,"text":"A","color":"#1E293B"},{"type":"text","x":258,"y":166,"text":"B","color":"#1E293B"},{"type":"text","x":58,"y":172,"text":"C","color":"#1E293B"},{"type":"arc","cx":76,"cy":44,"r":24,"startAngle":34,"sweepAngle":56,"color":"#0284C7"},{"type":"text","x":90,"y":74,"text":"∠A","color":"#0284C7"}]}}', 'ADMIN', 1, 104, 1, NULL, 0 FROM DUAL
