INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'g9', @ch_id, @gt_id, 'STATIC', 'ESSAY', '如图，为了测量河对岸一座信号塔 $AB$ 的高度，小明在河边地面 $C$ 处测得塔顶 $A$ 的仰角为 $30^\\circ$，沿射线 $CB$ 方向向塔底前进 $20$ 米到达 $D$ 处，再测得塔顶 $A$ 的仰角为 $60^\\circ$（点 $B$、$D$、$C$ 在同一直线上）。求信号塔 $AB$ 的高度（结果保留根号）。', '[]', '{"text":"解：\\n在 $\\\\triangle ADC$ 中，$\\\\angle ADB = 60^\\\\circ$ 是外角，$\\\\angle C = 30^\\\\circ$，\\n所以 $\\\\angle DAC = \\\\angle ADB - \\\\angle C = 60^\\\\circ - 30^\\\\circ = 30^\\\\circ = \\\\angle C$。\\n因此 $AD = CD = 20$（米）。\\n在 $\\\\text{Rt}\\\\triangle ABD$ 中，$\\\\angle ABD = 90^\\\\circ$，$\\\\angle ADB = 60^\\\\circ$，\\n所以 $AB = AD \\\\cdot \\\\mathrm{sin}\\\\,60^\\\\circ = 20 \\\\times \\\\frac{\\\\sqrt{3}}{2} = 10\\\\sqrt{3}$（米）。\\n答：信号塔 $AB$ 的高度为 $10\\\\sqrt{3}$ 米。"}', '【得分要点】发现外角倒角得等腰 $\\triangle ADC$（$AD=CD=20$）可极大简化计算，再在直角三角形中求出 $AB=10\\sqrt{3}$。', NULL, NULL, 4, '["双仰角外角等腰模型","手写解答","TASK-20261122-002"]', '{"diagram":{"title":"双仰角测信号塔高度示意图","width":320,"height":210,"primitives":[{"type":"line","x1":74,"y1":34,"x2":74,"y2":172,"color":"#0284C7"},{"type":"line","x1":48,"y1":172,"x2":286,"y2":172,"color":"#1E293B"},{"type":"line","x1":74,"y1":34,"x2":154,"y2":172,"color":"#DC2626"},{"type":"line","x1":74,"y1":34,"x2":268,"y2":172,"color":"#059669"},{"type":"rightAngle","vx":74,"vy":172,"ax":74,"ay":34,"bx":286,"by":172,"size":11,"color":"#0284C7"},{"type":"arc","cx":154,"cy":172,"r":24,"startAngle":-180,"sweepAngle":60,"color":"#DC2626"},{"type":"arc","cx":268,"cy":172,"r":30,"startAngle":-180,"sweepAngle":30,"color":"#059669"},{"type":"point","x":74,"y":34,"color":"#0284C7"},{"type":"point","x":74,"y":172,"color":"#1E293B"},{"type":"point","x":154,"y":172,"color":"#DC2626"},{"type":"point","x":268,"y":172,"color":"#059669"},{"type":"text","x":68,"y":14,"text":"A(塔顶)","color":"#0284C7"},{"type":"text","x":68,"y":178,"text":"B","color":"#1E293B"},{"type":"text","x":150,"y":178,"text":"D","color":"#DC2626"},{"type":"text","x":264,"y":178,"text":"C","color":"#059669"},{"type":"text","x":118,"y":152,"text":"60°","color":"#DC2626"},{"type":"text","x":216,"y":154,"text":"30°","color":"#059669"},{"type":"text","x":196,"y":180,"text":"20m","color":"#D97706"}]}}', 'ADMIN', 1, 105, 1, NULL, 0 FROM DUAL
