INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'g9', @ch_id, @gt_id, 'STATIC', 'ESSAY', '晚上，身高 $1.6$ 米的小华站在距离路灯灯杆底部 $4$ 米处，测得他的影子长是 $2$ 米。\n(1) 求该路灯灯泡距离地面的高度；\n(2) 若小华继续沿远离灯杆的方向走 $2$ 米（此时距离灯杆 $6$ 米），求他此时影子的长度。', '[]', '{"text":"解：\\n(1) 设路灯高度为 $H$ 米。\\n由中心投影下光线构成的相似三角形（A字型相似）：$\\\\frac{1.6}{H} = \\\\frac{2}{4 + 2} = \\\\frac{2}{6} = \\\\frac{1}{3}$，\\n解得 $H = 1.6 \\\\times 3 = 4.8$（米）。\\n(2) 设此时影子长为 $x$ 米。\\n同样由相似得：$\\\\frac{1.6}{4.8} = \\\\frac{x}{6 + x}$，即 $\\\\frac{1}{3} = \\\\frac{x}{6 + x}$，\\n交叉相乘得 $3x = 6 + x \\\\Rightarrow 2x = 6 \\\\Rightarrow x = 3$（米）。\\n答：路灯高 $4.8$ 米，此时影子长为 $3$ 米。"}', '【得分要点】正确建立路灯与人的中心投影相似三角形比例，注意分母是“人到灯杆距离 $+$ 影长”。', NULL, NULL, 3, '["中心投影路灯影长计算","手写解答","TASK-20261122-002"]', '{"diagram":{"title":"路灯中心投影相似模型","width":320,"height":210,"primitives":[{"type":"line","x1":26,"y1":172,"x2":294,"y2":172,"color":"#1E293B"},{"type":"line","x1":66,"y1":36,"x2":66,"y2":172,"color":"#0284C7"},{"type":"circle","cx":66,"cy":36,"r":6,"color":"#D97706","fillColor":"#FBBF24"},{"type":"line","x1":178,"y1":118,"x2":178,"y2":172,"color":"#059669"},{"type":"line","x1":66,"y1":36,"x2":250,"y2":172,"color":"#DC2626","dashed":true},{"type":"rightAngle","vx":66,"vy":172,"ax":66,"ay":36,"bx":250,"by":172,"size":9,"color":"#0284C7"},{"type":"rightAngle","vx":178,"vy":172,"ax":178,"ay":118,"bx":250,"by":172,"size":8,"color":"#059669"},{"type":"text","x":28,"y":92,"text":"H = ?","color":"#0284C7"},{"type":"text","x":148,"y":134,"text":"1.6m","color":"#059669"},{"type":"text","x":110,"y":178,"text":"4m","color":"#1E293B"},{"type":"text","x":204,"y":178,"text":"2m","color":"#DC2626"}]}}', 'ADMIN', 1, 104, 1, NULL, 0 FROM DUAL
