SELECT 'h1', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '设集合 $A = \\{1, 2, 3\\}$，集合 $B = \\{2, 3, 4\\}$，则 $A \\cap B =$（  ）', '["$\\\\{2, 3\\\\}$","$\\\\{1, 2, 3, 4\\\\}$","$\\\\{1, 4\\\\}$","$\\\\emptyset$"]', '{"index":0}', '交集取两集合公共元素，故 $A \\cap B = \\{2, 3\\}$。', NULL, NULL, 1, '["集合交集","TASK-20261122-002"]', '{"diagram":{"title":"集合交集与并集韦恩图","width":320,"height":210,"primitives":[{"type":"circle","cx":126,"cy":106,"r":58,"color":"#0284C7","fillColor":"#38BDF8"},{"type":"circle","cx":194,"cy":106,"r":58,"color":"#059669","fillColor":"#34D399"},{"type":"text","x":88,"y":98,"text":"A","color":"#0284C7"},{"type":"text","x":216,"y":98,"text":"B","color":"#059669"},{"type":"text","x":144,"y":98,"text":"A∩B","color":"#DC2626"}]}}', 'ADMIN', 1, 101, 1, NULL, 0 FROM DUAL
