SELECT 'h1', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '设集合 $A = \\{x \\mid x \\le {{a}}\\}$，$B = \\{x \\mid x \\ge 2\\}$。若 $A \\cap B$ 中恰好包含的整数个数有（  ）个', '[]', '{"index":0}', '$A \\cap B = [2, {{a}}]$，整数个数为 ${{a}} - 2 + 1 = {{a - 1}}$ 个。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"a":[2,6]},"stemTpl":"设集合 $A = \\\\{x \\\\mid x \\\\le {{a}}\\\\}$，$B = \\\\{x \\\\mid x \\\\ge 2\\\\}$。若 $A \\\\cap B$ 中恰好包含的整数个数有（  ）个","ansExpr":"a - 1","wrongExprs":["a","a - 2","a + 1"]}', 3, '["区间交集整数计数","TASK-20261122-002"]', '{"diagram":{"title":"数轴区间运算示意图","width":320,"height":210,"primitives":[{"type":"arrow","x1":26,"y1":134,"x2":294,"y2":134,"color":"#1E293B"},{"type":"polyline","points":[[72,134],[72,94],[198,94],[198,134]],"color":"#0284C7"},{"type":"polyline","points":[[134,134],[134,68],[254,68],[254,134]],"color":"#059669"},{"type":"polygon","points":[[134,94],[198,94],[198,134],[134,134]],"color":"#DC2626","fillColor":"#FBBF24"},{"type":"text","x":100,"y":78,"text":"A","color":"#0284C7"},{"type":"text","x":218,"y":52,"text":"B","color":"#059669"},{"type":"text","x":148,"y":108,"text":"A∩B","color":"#DC2626"}]}}', 'ADMIN', 1, 103, 1, NULL, 0 FROM DUAL
