SELECT 'h1', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '已知指数函数 $f(x) = {{a}}^x$，则 $f(2) - f(1)$ 等于（  ）', '[]', '{"index":0}', '$f(2) - f(1) = {{a}}^2 - {{a}} = {{a}}({{a}} - 1) = {{a*(a-1)}}$。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"a":[2,5]},"stemTpl":"已知指数函数 $f(x) = {{a}}^x$，则 $f(2) - f(1)$ 等于（  ）","ansExpr":"a * (a - 1)","wrongExprs":["a * a - 1","a - 1","a * (a + 1)"]}', 3, '["指数区间极差","TASK-20261122-002"]', '{"diagram":{"title":"指数函数图象与定点示意","width":320,"height":210,"primitives":[{"type":"arrow","x1":26,"y1":148,"x2":294,"y2":148,"color":"#64748B"},{"type":"arrow","x1":118,"y1":194,"x2":118,"y2":18,"color":"#64748B"},{"type":"text","x":284,"y":154,"text":"x","color":"#64748B"},{"type":"text","x":125,"y":16,"text":"y","color":"#64748B"},{"type":"text","x":105,"y":153,"text":"O","color":"#64748B"},{"type":"polyline","points":[[38,141],[42.9,140.4],[47.9,139.7],[52.8,138.9],[57.8,138.1],[62.7,137.3],[67.6,136.3],[72.6,135.3],[77.5,134.1],[82.5,132.9],[87.4,131.5],[92.4,130],[97.3,128.4],[102.2,126.7],[107.2,124.8],[112.1,122.7],[117.1,120.5],[122,118],[126.9,115.3],[131.9,112.4],[136.8,109.2],[141.8,105.7],[146.7,102],[151.6,97.8],[156.6,93.4],[161.5,88.5],[166.5,83.1],[171.4,77.3],[176.4,71],[181.3,64.2],[186.2,56.7],[191.2,48.5],[196.1,39.6],[201.1,29.9],[206,19.3]],"color":"#0284C7"},{"type":"point","x":118,"y":120,"label":"(0,1)","color":"#DC2626"},{"type":"text","x":204,"y":40,"text":"y = a^x","color":"#0284C7"}]}}', 'ADMIN', 1, 103, 1, NULL, 0 FROM DUAL
