SELECT 'h1', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '若角 $\\alpha$ 的终边经过点 $P(-3, 4)$，则 $\\mathrm{sin}\\,\\alpha$ 的值为（  ）', '["$\\\\frac{4}{5}$","$-\\\\frac{3}{5}$","$-\\\\frac{4}{3}$","$\\\\frac{3}{5}$"]', '{"index":0}', '$r = \\sqrt{(-3)^2 + 4^2} = 5$，由三角函数任意角定义 $\\mathrm{sin}\\,\\alpha = \\frac{y}{r} = \\frac{4}{5}$。', NULL, NULL, 1, '["任意角三角函数定义","TASK-20261122-002"]', '{"diagram":{"title":"正弦函数 y = A sin(ωx+φ) 波形示意","width":320,"height":210,"primitives":[{"type":"arrow","x1":26,"y1":108,"x2":294,"y2":108,"color":"#64748B"},{"type":"arrow","x1":46,"y1":194,"x2":46,"y2":18,"color":"#64748B"},{"type":"text","x":284,"y":114,"text":"x","color":"#64748B"},{"type":"text","x":53,"y":16,"text":"y","color":"#64748B"},{"type":"text","x":33,"y":113,"text":"O","color":"#64748B"},{"type":"polyline","points":[[46,108],[50.8,100.4],[55.6,93],[60.4,85.8],[65.2,79],[70,72.7],[74.8,67],[79.5,62],[84.3,57.8],[89.1,54.4],[93.9,52],[98.7,50.5],[103.5,50],[108.3,50.5],[113.1,52],[117.9,54.4],[122.7,57.8],[127.5,62],[132.3,67],[137,72.7],[141.8,79],[146.6,85.8],[151.4,93],[156.2,100.4],[161,108],[165.8,115.6],[170.6,123],[175.4,130.2],[180.2,137],[185,143.3],[189.8,149],[194.5,154],[199.3,158.2],[204.1,161.6],[208.9,164],[213.7,165.5],[218.5,166],[223.3,165.5],[228.1,164],[232.9,161.6],[237.7,158.2],[242.5,154],[247.3,149],[252,143.3],[256.8,137],[261.6,130.2],[266.4,123],[271.2,115.6],[276,108]],"color":"#0284C7"},{"type":"text","x":98,"y":34,"text":"A","color":"#DC2626"},{"type":"text","x":272,"y":118,"text":"T","color":"#0284C7"}]}}', 'ADMIN', 1, 102, 1, NULL, 0 FROM DUAL
