SELECT 'h1', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '已知平面向量 $a = (1, -2)$，$b = (3, 4)$，则向量 $a + b$ 的坐标为（  ）', '["$(4, 2)$","$(-2, -6)$","$(3, -8)$","$(2, 1)$"]', '{"index":0}', '向量加法坐标对应相加：$(1+3, -2+4) = (4, 2)$。', NULL, NULL, 1, '["向量加法坐标运算","TASK-20261122-002"]', '{"diagram":{"title":"平面向量平行四边形法则","width":320,"height":210,"primitives":[{"type":"arrow","x1":68,"y1":158,"x2":198,"y2":158,"color":"#0284C7"},{"type":"arrow","x1":68,"y1":158,"x2":128,"y2":66,"color":"#059669"},{"type":"arrow","x1":68,"y1":158,"x2":258,"y2":66,"color":"#DC2626"},{"type":"line","x1":198,"y1":158,"x2":258,"y2":66,"color":"#64748B","dashed":true},{"type":"line","x1":128,"y1":66,"x2":258,"y2":66,"color":"#64748B","dashed":true},{"type":"text","x":124,"y":164,"text":"a","color":"#0284C7"},{"type":"text","x":80,"y":102,"text":"b","color":"#059669"},{"type":"text","x":174,"y":96,"text":"a + b","color":"#DC2626"}]}}', 'ADMIN', 1, 101, 1, NULL, 0 FROM DUAL
