SELECT 'h1', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '已知向量 $a = (2, 1)$，$b = (-1, m)$。若 $a \\perp b$，则实数 $m$ 的值为（  ）', '["$2$","$-2$","$\\\\frac{1}{2}$","$-\\\\frac{1}{2}$"]', '{"index":0}', '两向量垂直充要条件：数量积 $a \\cdot b = 2\\times (-1) + 1 \\times m = 0 \\Rightarrow m = 2$。', NULL, NULL, 1, '["向量垂直条件","TASK-20261122-002"]', '{"diagram":{"title":"平面向量平行四边形法则","width":320,"height":210,"primitives":[{"type":"arrow","x1":68,"y1":158,"x2":198,"y2":158,"color":"#0284C7"},{"type":"arrow","x1":68,"y1":158,"x2":128,"y2":66,"color":"#059669"},{"type":"arrow","x1":68,"y1":158,"x2":258,"y2":66,"color":"#DC2626"},{"type":"line","x1":198,"y1":158,"x2":258,"y2":66,"color":"#64748B","dashed":true},{"type":"line","x1":128,"y1":66,"x2":258,"y2":66,"color":"#64748B","dashed":true},{"type":"text","x":124,"y":164,"text":"a","color":"#0284C7"},{"type":"text","x":80,"y":102,"text":"b","color":"#059669"},{"type":"text","x":174,"y":96,"text":"a + b","color":"#DC2626"}]}}', 'ADMIN', 1, 102, 1, NULL, 0 FROM DUAL
