SELECT 'h1', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '已知 $|a| = 2$，$|b| = 3$，且 $a$ 与 $b$ 的夹角为 $60^\\circ$，则 $a \\cdot b =$（  ）', '["$3$","$3\\\\sqrt{3}$","$6$","$-3$"]', '{"index":0}', '$a \\cdot b = |a||b|\\mathrm{cos}\\,60^\\circ = 2 \\times 3 \\times \\frac{1}{2} = 3$。', NULL, NULL, 2, '["向量数量积定义","TASK-20261122-002"]', '{"diagram":{"title":"平面向量夹角与数量积示意","width":320,"height":210,"primitives":[{"type":"arrow","x1":66,"y1":156,"x2":258,"y2":156,"color":"#0284C7"},{"type":"arrow","x1":66,"y1":156,"x2":146,"y2":44,"color":"#DC2626"},{"type":"arc","cx":66,"cy":156,"r":36,"startAngle":-54,"sweepAngle":54,"color":"#D97706"},{"type":"point","x":66,"y":156,"label":"O","color":"#1E293B"},{"type":"text","x":152,"y":164,"text":"|b| = 3","color":"#0284C7"},{"type":"text","x":78,"y":86,"text":"|a| = 2","color":"#DC2626"},{"type":"text","x":108,"y":132,"text":"60°","color":"#D97706"}]}}', 'ADMIN', 1, 101, 1, NULL, 0 FROM DUAL
