SELECT 'h1', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '已知平面向量 $a = ({{a}}, 0)$，$b = (1, \\sqrt{3})$，则数量积 $a \\cdot b$ 等于（  ）', '[]', '{"index":0}', '$a \\cdot b = {{a}} \\times 1 + 0 \\times \\sqrt{3} = {{a}}$。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"a":[2,6]},"stemTpl":"已知平面向量 $a = ({{a}}, 0)$，$b = (1, \\\\sqrt{3})$，则数量积 $a \\\\cdot b$ 等于（  ）","ansExpr":"a","wrongExprs":["2 * a","3 * a","0"]}', 2, '["坐标数量积","TASK-20261122-002"]', '{"diagram":{"title":"平面向量平行四边形法则","width":320,"height":210,"primitives":[{"type":"arrow","x1":68,"y1":158,"x2":198,"y2":158,"color":"#0284C7"},{"type":"arrow","x1":68,"y1":158,"x2":128,"y2":66,"color":"#059669"},{"type":"arrow","x1":68,"y1":158,"x2":258,"y2":66,"color":"#DC2626"},{"type":"line","x1":198,"y1":158,"x2":258,"y2":66,"color":"#64748B","dashed":true},{"type":"line","x1":128,"y1":66,"x2":258,"y2":66,"color":"#64748B","dashed":true},{"type":"text","x":124,"y":164,"text":"a","color":"#0284C7"},{"type":"text","x":80,"y":102,"text":"b","color":"#059669"},{"type":"text","x":174,"y":96,"text":"a + b","color":"#DC2626"}]}}', 'ADMIN', 1, 103, 1, NULL, 0 FROM DUAL
