SELECT 'h1', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '已知一个球的半径为 $3$，则该球的表面积和体积分别是（  ）', '["$36\\\\pi$，$36\\\\pi$","$9\\\\pi$，$36\\\\pi$","$36\\\\pi$，$27\\\\pi$","$18\\\\pi$，$36\\\\pi$"]', '{"index":0}', '$S_{\\text{球}} = 4\\pi R^2 = 36\\pi$，$V_{\\text{球}} = \\frac{4}{3}\\pi R^3 = 36\\pi$。', NULL, NULL, 1, '["球表面积与体积","TASK-20261122-002"]', '{"diagram":{"title":"球体与外接球示意图","width":320,"height":210,"primitives":[{"type":"circle","cx":160,"cy":106,"r":70,"color":"#1E293B","fillColor":"#38BDF8"},{"type":"line","x1":90,"y1":106,"x2":230,"y2":106,"color":"#64748B","dashed":true},{"type":"line","x1":160,"y1":106,"x2":210,"y2":56,"color":"#DC2626"},{"type":"point","x":160,"y":106,"label":"O","color":"#DC2626"},{"type":"text","x":186,"y":66,"text":"R","color":"#DC2626"}]}}', 'ADMIN', 1, 101, 1, NULL, 0 FROM DUAL
