SELECT 'h1', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '用斜二测画法画边长为 ${{2*s}}$ 的水平放置正方形的直观图（平行四边形），则该直观图的面积除以 $\\sqrt{2}$ 等于（  ）', '[]', '{"index":0}', '原正方形面积为 $({{2*s}})^2 = {{4*s*s}}$，由斜二测画法面积公式 $S_{\\text{直观}} = \\frac{\\sqrt{2}}{4} S_{\\text{原}}$，得面积为 ${{s*s}}\\sqrt{2}$。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"s":[2,6]},"stemTpl":"用斜二测画法画边长为 ${{2*s}}$ 的水平放置正方形的直观图（平行四边形），则该直观图的面积除以 $\\\\sqrt{2}$ 等于（  ）","ansExpr":"s * s","wrongExprs":["2 * s * s","4 * s * s","s * s / 2"]}', 2, '["斜二测画法面积比","TASK-20261122-002"]', '{"diagram":{"title":"斜二测画法直观图（边长 {{2*s}}）","width":320,"height":210,"primitives":[{"type":"polygon","points":[[30,62],[116,62],[116,148],[30,148]],"color":"#1E293B","fillColor":"#38BDF8"},{"type":"text","x":44,"y":156,"text":"原正方形","color":"#64748B"},{"type":"text","x":62,"y":134,"text":"{{2*s}}","color":"#0284C7"},{"type":"arrow","x1":128,"y1":106,"x2":158,"y2":106,"color":"#DC2626"},{"type":"polygon","points":[[172,148],[258,148],[288,118],[202,118]],"color":"#0284C7","fillColor":"#FBBF24"},{"type":"arc","cx":172,"cy":148,"r":22,"startAngle":-45,"sweepAngle":45,"color":"#DC2626"},{"type":"text","x":196,"y":130,"text":"45°","color":"#DC2626"},{"type":"text","x":192,"y":156,"text":"底不变、斜边减半","color":"#64748B"}]}}', 'ADMIN', 1, 104, 1, NULL, 0 FROM DUAL
