SELECT 'h1', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '一个正三棱柱的底面边长为 ${{2*a}}$，侧棱长为 $3$，则它的体积除以 $\\sqrt{3}$ 等于（  ）', '[]', '{"index":0}', '正三角形底面积 $S = \\frac{\\sqrt{3}}{4}({{2*a}})^2 = {{a*a}}\\sqrt{3}$，乘以高 $3$ 得体积 $3{{a*a}}\\sqrt{3}$。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"a":[2,5]},"stemTpl":"一个正三棱柱的底面边长为 ${{2*a}}$，侧棱长为 $3$，则它的体积除以 $\\\\sqrt{3}$ 等于（  ）","ansExpr":"3 * a * a","wrongExprs":["a * a","6 * a * a","4 * a * a"]}', 3, '["正三棱柱体积","TASK-20261122-002"]', '{"diagram":{"title":"正方体/长方体示意图","width":320,"height":210,"primitives":[{"type":"polygon","points":[[82,72],[198,72],[198,174],[82,174]],"color":"#1E293B","fillColor":"#38BDF8"},{"type":"line","x1":82,"y1":72,"x2":130,"y2":36,"color":"#1E293B"},{"type":"line","x1":198,"y1":72,"x2":246,"y2":36,"color":"#1E293B"},{"type":"line","x1":130,"y1":36,"x2":246,"y2":36,"color":"#1E293B"},{"type":"line","x1":246,"y1":36,"x2":246,"y2":138,"color":"#1E293B"},{"type":"line","x1":198,"y1":174,"x2":246,"y2":138,"color":"#1E293B"},{"type":"line","x1":130,"y1":36,"x2":130,"y2":138,"color":"#64748B","dashed":true},{"type":"line","x1":82,"y1":174,"x2":130,"y2":138,"color":"#64748B","dashed":true},{"type":"line","x1":130,"y1":138,"x2":246,"y2":138,"color":"#64748B","dashed":true}]}}', 'ADMIN', 1, 103, 1, NULL, 0 FROM DUAL
