INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'h1', @ch_id, @gt_id, 'STATIC', 'ESSAY', '某校举办“趣味物理与数学”闯关赛，甲、乙两名同学各自独立参加三轮答题，每轮答对分别得 $1$ 分、答错得 $0$ 分。已知甲每轮答对的概率均为 $\\frac{2}{3}$，乙每轮答对的概率均为 $\\frac{1}{2}$。\n(1) 求甲在三轮答题中恰好答对 $2$ 轮的概率；\n(2) 求甲、乙两人至少有一人能全部答对三轮的概率。', '[]', '{"text":"解：\\n(1) 甲三轮中恰答对 $2$ 轮包含 $3$ 种互斥情况（对对错、对错对、错对对），\\n每种概率均为 $\\\\left(\\\\frac{2}{3}\\\\right)^2 \\\\times \\\\left(1 - \\\\frac{2}{3}\\\\right) = \\\\frac{4}{27}$，\\n所以 $P = 3 \\\\times \\\\frac{4}{27} = \\\\frac{4}{9}$。\\n(2) 甲全对的概率 $P(\\\\text{甲全对}) = \\\\left(\\\\frac{2}{3}\\\\right)^3 = \\\\frac{8}{27}$；\\n乙全对的概率 $P(\\\\text{乙全对}) = \\\\left(\\\\frac{1}{2}\\\\right)^3 = \\\\frac{1}{8}$。\\n由于两人答题相互独立，利用对立事件计算：\\n$P(\\\\text{至少一人全对}) = 1 - \\\\left(1 - \\\\frac{8}{27}\\\\right)\\\\left(1 - \\\\frac{1}{8}\\\\right) = 1 - \\\\frac{19}{27} \\\\times \\\\frac{7}{8} = 1 - \\\\frac{133}{216} = \\\\frac{83}{216}$。"}', '【得分要点】(1) 不遗漏排列数 $3$ 算得 $\\frac{4}{9}$；(2) 用“正难则反”对立事件公式算得 $\\frac{83}{216}$。', NULL, NULL, 3, '["独立重复事件概率","手写解答","TASK-20261122-002"]', NULL, 'ADMIN', 1, 104, 1, NULL, 0 FROM DUAL
