INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'h1', @ch_id, @gt_id, 'STATIC', 'ESSAY', '某智能测试系统有三道独立关卡 $A, B, C$，规定挑战者必须通过全部三道关卡才算“通关”。已知某学生通过 $A$ 关的概率为 $\\frac{3}{4}$，通过 $B$ 关的概率为 $\\frac{2}{3}$，通过 $C$ 关的概率为 $\\frac{1}{2}$，且各关是否通过相互独立。\n(1) 求该学生成功“通关”的概率；\n(2) 求该学生在三道关卡中“至少通过两道关卡”的概率。', '[]', '{"text":"解：\\n(1) 全部通关即三关都通过：$P = \\\\frac{3}{4} \\\\times \\\\frac{2}{3} \\\\times \\\\frac{1}{2} = \\\\frac{1}{4}$。\\n(2) “至少通过两道”包括“恰通过两道”和“三道全通”：\\n① 恰通过 $A, B$ 未过 $C$：$\\\\frac{3}{4} \\\\times \\\\frac{2}{3} \\\\times \\\\frac{1}{2} = \\\\frac{6}{24}$；\\n② 恰通过 $A, C$ 未过 $B$：$\\\\frac{3}{4} \\\\times \\\\frac{1}{3} \\\\times \\\\frac{1}{2} = \\\\frac{3}{24}$；\\n③ 恰通过 $B, C$ 未过 $A$：$\\\\frac{1}{4} \\\\times \\\\frac{2}{3} \\\\times \\\\frac{1}{2} = \\\\frac{2}{24}$；\\n④ 三道全通：$\\\\frac{1}{4} = \\\\frac{6}{24}$。\\n相加得 $P = \\\\frac{6 + 3 + 2 + 6}{24} = \\\\frac{17}{24}$。"}', '【得分要点】清晰拆分四种互斥事件，逐一用独立乘法算出概率并求和得出 $\\frac{17}{24}$。', NULL, NULL, 4, '["三事件独立综合概率","手写解答","TASK-20261122-002"]', NULL, 'ADMIN', 1, 105, 1, NULL, 0 FROM DUAL
WHERE @ch_id IS NOT NULL AND @gt_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM edu_question WHERE gate_id = @gt_id AND deleted = 0 AND sort_order = 105 AND JSON_CONTAINS(tags_json, '"TASK-20261122-002"'));

