SELECT 'h2', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '已知空间向量 $a = (1, 2, -1)$，$b = (2, -1, 0)$，则 $a \\cdot b =$（  ）', '["$0$","$4$","$-1$","$1$"]', '{"index":0}', '空间数量积 $a \\cdot b = 1\\times 2 + 2\\times (-1) + (-1)\\times 0 = 0$。', NULL, NULL, 1, '["空间向量数量积","TASK-20261122-002"]', '{"diagram":{"title":"正方体/长方体示意图","width":320,"height":210,"primitives":[{"type":"polygon","points":[[82,72],[198,72],[198,174],[82,174]],"color":"#1E293B","fillColor":"#38BDF8"},{"type":"line","x1":82,"y1":72,"x2":130,"y2":36,"color":"#1E293B"},{"type":"line","x1":198,"y1":72,"x2":246,"y2":36,"color":"#1E293B"},{"type":"line","x1":130,"y1":36,"x2":246,"y2":36,"color":"#1E293B"},{"type":"line","x1":246,"y1":36,"x2":246,"y2":138,"color":"#1E293B"},{"type":"line","x1":198,"y1":174,"x2":246,"y2":138,"color":"#1E293B"},{"type":"line","x1":130,"y1":36,"x2":130,"y2":138,"color":"#64748B","dashed":true},{"type":"line","x1":82,"y1":174,"x2":130,"y2":138,"color":"#64748B","dashed":true},{"type":"line","x1":130,"y1":138,"x2":246,"y2":138,"color":"#64748B","dashed":true}]}}', 'ADMIN', 1, 102, 1, NULL, 0 FROM DUAL
