SELECT 'h2', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '已知空间向量 $m = (1, -2, {{a}})$ 与 $n = (2, k, 6)$ 垂直，则实数 $k$ 的值为（  ）', '[]', '{"index":0}', '由 $m \\cdot n = 0$ 得 $2 - 2k + 6\\times {{a}} = 0 \\Rightarrow 2k = 6\\times {{a}} + 2 \\Rightarrow k = {{3*a+1}}$。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"a":[2,6]},"stemTpl":"已知空间向量 $m = (1, -2, {{a}})$ 与 $n = (2, k, 6)$ 垂直，则实数 $k$ 的值为（  ）","ansExpr":"3 * a + 1","wrongExprs":["3 * a - 1","6 * a + 2","a + 1"]}', 1, '["空间向量垂直求参","TASK-20261122-002"]', '{"diagram":{"title":"正方体/长方体示意图","width":320,"height":210,"primitives":[{"type":"polygon","points":[[82,72],[198,72],[198,174],[82,174]],"color":"#1E293B","fillColor":"#38BDF8"},{"type":"line","x1":82,"y1":72,"x2":130,"y2":36,"color":"#1E293B"},{"type":"line","x1":198,"y1":72,"x2":246,"y2":36,"color":"#1E293B"},{"type":"line","x1":130,"y1":36,"x2":246,"y2":36,"color":"#1E293B"},{"type":"line","x1":246,"y1":36,"x2":246,"y2":138,"color":"#1E293B"},{"type":"line","x1":198,"y1":174,"x2":246,"y2":138,"color":"#1E293B"},{"type":"line","x1":130,"y1":36,"x2":130,"y2":138,"color":"#64748B","dashed":true},{"type":"line","x1":82,"y1":174,"x2":130,"y2":138,"color":"#64748B","dashed":true},{"type":"line","x1":130,"y1":138,"x2":246,"y2":138,"color":"#64748B","dashed":true}]}}', 'ADMIN', 1, 103, 1, NULL, 0 FROM DUAL
