INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'h2', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '已知直线 $l$ 的方向向量 $v = (1, -1, 2)$，平面 $\\alpha$ 的法向量 $n = (-2, 2, -4)$，则直线 $l$ 与平面 $\\alpha$ 的位置关系是（  ）', '["$l \\\\perp \\\\alpha$","$l \\\\parallel \\\\alpha$","$l \\\\subset \\\\alpha$","$l$ 与 $\\\\alpha$ 斜交"]', '{"index":0}', '因为 $n = -2v$，即直线的方向向量与平面法向量平行，故 $l \\perp \\alpha$。', NULL, NULL, 2, '["方向向量与法向量判定","TASK-20261122-002"]', '{"diagram":{"title":"正方体/长方体示意图","width":320,"height":210,"primitives":[{"type":"polygon","points":[[82,72],[198,72],[198,174],[82,174]],"color":"#1E293B","fillColor":"#38BDF8"},{"type":"line","x1":82,"y1":72,"x2":130,"y2":36,"color":"#1E293B"},{"type":"line","x1":198,"y1":72,"x2":246,"y2":36,"color":"#1E293B"},{"type":"line","x1":130,"y1":36,"x2":246,"y2":36,"color":"#1E293B"},{"type":"line","x1":246,"y1":36,"x2":246,"y2":138,"color":"#1E293B"},{"type":"line","x1":198,"y1":174,"x2":246,"y2":138,"color":"#1E293B"},{"type":"line","x1":130,"y1":36,"x2":130,"y2":138,"color":"#64748B","dashed":true},{"type":"line","x1":82,"y1":174,"x2":130,"y2":138,"color":"#64748B","dashed":true},{"type":"line","x1":130,"y1":138,"x2":246,"y2":138,"color":"#64748B","dashed":true}]}}', 'ADMIN', 1, 101, 1, NULL, 0 FROM DUAL
