INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'h2', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '已知平面 $\\alpha$ 的法向量为 $n_1 = (1, 0, 1)$，平面 $\\beta$ 的法向量为 $n_2 = (0, 1, 1)$，则平面 $\\alpha$ 与平面 $\\beta$ 所成锐二面角的大小是（  ）', '["$60^\\\\circ$","$30^\\\\circ$","$45^\\\\circ$","$90^\\\\circ$"]', '{"index":0}', '$|\\mathrm{cos}\\,\\theta| = \\frac{|n_1\\cdot n_2|}{|n_1||n_2|} = \\frac{1}{\\sqrt{2}\\cdot\\sqrt{2}} = \\frac{1}{2}$，故锐二面角为 $60^\\circ$。', NULL, NULL, 4, '["法向量求二面角","TASK-20261122-002"]', '{"diagram":{"title":"正方体/长方体示意图","width":320,"height":210,"primitives":[{"type":"polygon","points":[[82,72],[198,72],[198,174],[82,174]],"color":"#1E293B","fillColor":"#38BDF8"},{"type":"line","x1":82,"y1":72,"x2":130,"y2":36,"color":"#1E293B"},{"type":"line","x1":198,"y1":72,"x2":246,"y2":36,"color":"#1E293B"},{"type":"line","x1":130,"y1":36,"x2":246,"y2":36,"color":"#1E293B"},{"type":"line","x1":246,"y1":36,"x2":246,"y2":138,"color":"#1E293B"},{"type":"line","x1":198,"y1":174,"x2":246,"y2":138,"color":"#1E293B"},{"type":"line","x1":130,"y1":36,"x2":130,"y2":138,"color":"#64748B","dashed":true},{"type":"line","x1":82,"y1":174,"x2":130,"y2":138,"color":"#64748B","dashed":true},{"type":"line","x1":130,"y1":138,"x2":246,"y2":138,"color":"#64748B","dashed":true}]}}', 'ADMIN', 1, 101, 1, NULL, 0 FROM DUAL
