SELECT 'h2', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '经过两点 $A(1, 2)$ 和 $B(3, 6)$ 的直线的斜率是（  ）', '["$2$","$\\\\frac{1}{2}$","$-2$","$4$"]', '{"index":0}', '斜率 $k = \\frac{6 - 2}{3 - 1} = \\frac{4}{2} = 2$。', NULL, NULL, 1, '["两点斜率公式","TASK-20261122-002"]', '{"diagram":{"title":"过 A(1,2)、B(3,6) 直线斜率示意","width":320,"height":210,"primitives":[{"type":"arrow","x1":26,"y1":172,"x2":290,"y2":172,"color":"#64748B"},{"type":"arrow","x1":64,"y1":194,"x2":64,"y2":16,"color":"#64748B"},{"type":"text","x":280,"y":178,"text":"x","color":"#64748B"},{"type":"text","x":71,"y":14,"text":"y","color":"#64748B"},{"type":"text","x":51,"y":177,"text":"O","color":"#64748B"},{"type":"line","x1":73.2,"y1":163.2,"x2":220.4,"y2":22.400000000000006,"color":"#0284C7"},{"type":"line","x1":110,"y1":128,"x2":202,"y2":128,"color":"#DC2626","dashed":true},{"type":"line","x1":202,"y1":128,"x2":202,"y2":40,"color":"#DC2626","dashed":true},{"type":"point","x":110,"y":128,"label":"A(1,2)","color":"#0284C7"},{"type":"point","x":202,"y":40,"label":"B(3,6)","color":"#0284C7"},{"type":"text","x":154,"y":134,"text":"Δx","color":"#DC2626"},{"type":"text","x":208,"y":82,"text":"Δy","color":"#DC2626"}]}}', 'ADMIN', 1, 101, 1, NULL, 0 FROM DUAL
