INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'h2', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '若直线 $ax + 2y - 1 = 0$ 与直线 $3x + (a + 1)y + 2 = 0$ 平行，则 $a$ 的值为（  ）', '["$-3$ 或 $2$","$2$","$-3$","$1$"]', '{"index":0}', '由平行条件 $a(a+1) = 6 \\Rightarrow a^2 + a - 6 = 0 \\Rightarrow a = -3$ 或 $2$。检验重合：当 $a=2$ 时两线为 $2x+2y-1=0$ 与 $3x+3y+2=0$ 不重合；当 $a=-3$ 时为 $-3x+2y-1=0$ 与 $3x-2y+2=0$ 也不重合，故 $-3$ 和 $2$ 均有效。', NULL, NULL, 2, '["两直线平行与重合检验","TASK-20261122-002"]', '{"diagram":{"title":"平行线与截线 (a ∥ b)","width":320,"height":210,"primitives":[{"type":"line","x1":36,"y1":62,"x2":284,"y2":62,"color":"#1E293B"},{"type":"line","x1":36,"y1":148,"x2":284,"y2":148,"color":"#1E293B"},{"type":"line","x1":108,"y1":22,"x2":212,"y2":188,"color":"#0284C7"},{"type":"arc","cx":133,"cy":62,"r":18,"startAngle":0,"sweepAngle":58,"color":"#DC2626"},{"type":"arc","cx":187,"cy":148,"r":18,"startAngle":-180,"sweepAngle":58,"color":"#059669"},{"type":"text","x":28,"y":56,"text":"a","color":"#1E293B"},{"type":"text","x":28,"y":142,"text":"b","color":"#1E293B"},{"type":"text","x":154,"y":68,"text":"∠1","color":"#DC2626"},{"type":"text","x":146,"y":128,"text":"∠2","color":"#059669"}]}}', 'ADMIN', 1, 101, 1, NULL, 0 FROM DUAL
