INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'h2', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '已知圆 $C: (x - 1)^2 + (y - 2)^2 = 4$，过圆内一点 $P(2, 1)$ 的所有弦中，最短弦的长度是（  ）', '["$2\\\\sqrt{2}$","$2$","$4$","$2\\\\sqrt{3}$"]', '{"index":0}', '过圆内一点最短的弦垂直于 $CP$。$|CP| = \\sqrt{(2-1)^2 + (1-2)^2} = \\sqrt{2}$，半径 $r = 2$，最短弦长 $= 2\\sqrt{r^2 - |CP|^2} = 2\\sqrt{4 - 2} = 2\\sqrt{2}$。', NULL, NULL, 4, '["圆内过定点最短弦","TASK-20261122-002"]', '{"diagram":{"title":"直线与圆的位置关系示意图","width":320,"height":210,"primitives":[{"type":"circle","cx":138,"cy":108,"r":62,"color":"#1E293B","fillColor":"#38BDF8"},{"type":"line","x1":138,"y1":108,"x2":186,"y2":68,"color":"#DC2626"},{"type":"line","x1":72,"y1":30,"x2":266,"y2":176,"color":"#0284C7"},{"type":"rightAngle","vx":186,"vy":68,"ax":138,"ay":108,"bx":266,"by":176,"size":9,"color":"#DC2626"},{"type":"point","x":138,"y":108,"label":"C","color":"#1E293B"},{"type":"text","x":158,"y":76,"text":"d","color":"#DC2626"},{"type":"text","x":244,"y":148,"text":"l","color":"#0284C7"}]}}', 'ADMIN', 1, 101, 1, NULL, 0 FROM DUAL
