SELECT 'h2', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '椭圆 $\\frac{x^2}{25} + \\frac{y^2}{16} = 1$ 的长轴长和焦距分别是（  ）', '["$10$，$6$","$5$，$3$","$10$，$3$","$25$，$9$"]', '{"index":0}', '$a^2 = 25 \\Rightarrow a = 5$（长轴 $2a=10$）；$b^2=16$，则 $c = \\sqrt{25-16} = 3$（焦距 $2c=6$）。', NULL, NULL, 1, '["椭圆基本量","TASK-20261122-002"]', '{"diagram":{"title":"椭圆焦点与标准方程示意图","width":320,"height":210,"primitives":[{"type":"arrow","x1":24,"y1":108,"x2":296,"y2":108,"color":"#64748B"},{"type":"arrow","x1":160,"y1":194,"x2":160,"y2":18,"color":"#64748B"},{"type":"text","x":286,"y":114,"text":"x","color":"#64748B"},{"type":"text","x":167,"y":16,"text":"y","color":"#64748B"},{"type":"text","x":147,"y":113,"text":"O","color":"#64748B"},{"type":"polyline","points":[[256,108],[255.2,115.3],[252.7,122.5],[248.7,129.4],[243.1,136],[236.2,142.1],[227.9,147.6],[218.4,152.4],[208,156.5],[196.7,159.7],[184.8,162.1],[172.5,163.5],[160,164],[147.5,163.5],[135.2,162.1],[123.3,159.7],[112,156.5],[101.6,152.4],[92.1,147.6],[83.8,142.1],[76.9,136],[71.3,129.4],[67.3,122.5],[64.8,115.3],[64,108],[64.8,100.7],[67.3,93.5],[71.3,86.6],[76.9,80],[83.8,73.9],[92.1,68.4],[101.6,63.6],[112,59.5],[123.3,56.3],[135.2,53.9],[147.5,52.5],[160,52],[172.5,52.5],[184.8,53.9],[196.7,56.3],[208,59.5],[218.4,63.6],[227.9,68.4],[236.2,73.9],[243.1,80],[248.7,86.6],[252.7,93.5],[255.2,100.7],[256,108]],"color":"#0284C7"},{"type":"point","x":82,"y":108,"label":"F₁","color":"#DC2626"},{"type":"point","x":238,"y":108,"label":"F₂","color":"#DC2626"},{"type":"point","x":202,"y":58,"label":"P","color":"#059669"},{"type":"line","x1":82,"y1":108,"x2":202,"y2":58,"color":"#059669","dashed":true},{"type":"line","x1":238,"y1":108,"x2":202,"y2":58,"color":"#059669","dashed":true}]}}', 'ADMIN', 1, 101, 1, NULL, 0 FROM DUAL
