SELECT 'h2', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '双曲线 $\\frac{x^2}{9} - \\frac{y^2}{16} = 1$ 的渐近线方程是（  ）', '["$y = \\\\pm \\\\frac{4}{3}x$","$y = \\\\pm \\\\frac{3}{4}x$","$y = \\\\pm \\\\frac{5}{3}x$","$y = \\\\pm \\\\frac{16}{9}x$"]', '{"index":0}', '焦点在 $x$ 轴上的双曲线渐近线为 $y = \\pm \\frac{b}{a}x = \\pm \\frac{4}{3}x$。', NULL, NULL, 1, '["双曲线渐近线","TASK-20261122-002"]', '{"diagram":{"title":"双曲线与渐近线示意图","width":320,"height":210,"primitives":[{"type":"arrow","x1":24,"y1":108,"x2":296,"y2":108,"color":"#64748B"},{"type":"arrow","x1":160,"y1":194,"x2":160,"y2":18,"color":"#64748B"},{"type":"text","x":286,"y":114,"text":"x","color":"#64748B"},{"type":"text","x":167,"y":16,"text":"y","color":"#64748B"},{"type":"text","x":147,"y":113,"text":"O","color":"#64748B"},{"type":"line","x1":52,"y1":24,"x2":268,"y2":192,"color":"#64748B","dashed":true},{"type":"line","x1":52,"y1":192,"x2":268,"y2":24,"color":"#64748B","dashed":true},{"type":"polyline","points":[[267,202.1],[263.6,198.7],[260.3,195.3],[256.9,191.9],[253.5,188.5],[250.1,185.1],[246.7,181.6],[243.3,178.2],[240,174.6],[236.6,171.1],[233.2,167.5],[229.8,163.8],[226.4,160.1],[223.1,156.3],[219.7,152.4],[216.3,148.4],[212.9,144.2],[209.5,139.7],[206.1,134.9],[202.8,129.5],[199.4,122.9],[196,108],[196,108],[199.4,93.1],[202.8,86.5],[206.1,81.1],[209.5,76.3],[212.9,71.8],[216.3,67.6],[219.7,63.6],[223.1,59.7],[226.4,55.9],[229.8,52.2],[233.2,48.5],[236.6,44.9],[240,41.4],[243.3,37.8],[246.7,34.4],[250.1,30.9],[253.5,27.5],[256.9,24.1],[260.3,20.7],[263.6,17.3],[267,13.9],[270.4,10.6]],"color":"#0284C7"},{"type":"polyline","points":[[49.6,10.6],[53,13.9],[56.4,17.3],[59.7,20.7],[63.1,24.1],[66.5,27.5],[69.9,30.9],[73.3,34.4],[76.7,37.8],[80,41.4],[83.4,44.9],[86.8,48.5],[90.2,52.2],[93.6,55.9],[96.9,59.7],[100.3,63.6],[103.7,67.6],[107.1,71.8],[110.5,76.3],[113.9,81.1],[117.2,86.5],[120.6,93.1],[124,108],[124,108],[120.6,122.9],[117.2,129.5],[113.9,134.9],[110.5,139.7],[107.1,144.2],[103.7,148.4],[100.3,152.4],[96.9,156.3],[93.6,160.1],[90.2,163.8],[86.8,167.5],[83.4,171.1],[80,174.6],[76.7,178.2],[73.3,181.6],[69.9,185.1],[66.5,188.5],[63.1,191.9],[59.7,195.3],[56.4,198.7],[53,202.1]],"color":"#0284C7"},{"type":"point","x":106,"y":108,"label":"F₁","color":"#DC2626"},{"type":"point","x":214,"y":108,"label":"F₂","color":"#DC2626"}]}}', 'ADMIN', 1, 102, 1, NULL, 0 FROM DUAL
