SELECT 'h2', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '计算组合数 $C_6^2$ 与排列数 $A_4^2$ 的和为（  ）', '["$27$","$42$","$15$","$12$"]', '{"index":0}', '$C_6^2 = \\frac{6\\times 5}{2} = 15$，$A_4^2 = 4 \\times 3 = 12$，和为 $27$。', NULL, NULL, 1, '["排列数与组合数计算","TASK-20261122-002"]', NULL, 'ADMIN', 1, 102, 1, NULL, 0 FROM DUAL
