INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'h2', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '从装有 $3$ 个正品和 ${{n}}$ 个次品的盒中不放回任取 $2$ 件产品，记取出的正品数 $X$ 服从超几何分布，则该超几何分布的数学期望 $E(X)$ 为（  ）', '[]', '{"index":0}', '超几何分布期望公式 $E(X) = n \\cdot \\frac{M}{N} = 2 \\times \\frac{3}{ {{n}}+3} = \\frac{6}{ {{n+3}} }$。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"n":[4,9]},"stemTpl":"从装有 $3$ 个正品和 ${{n}}$ 个次品的盒中不放回任取 $2$ 件产品，记取出的正品数 $X$ 服从超几何分布，则该超几何分布的数学期望 $E(X)$ 为（  ）","ansExpr":"frac(6, n + 3)","wrongExprs":["frac(3, n + 3)","frac(2 * n, n + 3)","frac(6, n)"]}', 3, '["超几何分布期望公式","TASK-20261122-002"]', NULL, 'ADMIN', 1, 103, 1, NULL, 0 FROM DUAL
