INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'h3', @ch_id, @gt_id, 'STATIC', 'SINGLE_CHOICE', '设 $a = \\frac{\\mathrm{ln}\\,2}{2}$，$b = \\frac{\\mathrm{ln}\\,3}{3}$，$c = \\frac{\\mathrm{ln}\\,5}{5}$，则 $a, b, c$ 的大小关系是（  ）', '["$b > a > c$","$a > b > c$","$c > b > a$","$b > c > a$"]', '{"index":0}', '构造函数 $g(x) = \\frac{\\mathrm{ln}\\,x}{x}$，$g\'(x) = \\frac{1 - \\mathrm{ln}\\,x}{x^2}$，可知 $g(x)$ 在 $(e, +\\infty)$ 上单调递减。又 $a = \\frac{\\mathrm{ln}\\,2}{2} = \\frac{\\mathrm{ln}\\,4}{4} = g(4)$，且 $e < 3 < 4 < 5$，因此 $g(3) > g(4) > g(5)$，即 $b > a > c$。', NULL, NULL, 2, '["构造函数比大小","TASK-20261122-002"]', NULL, 'ADMIN', 1, 102, 1, NULL, 0 FROM DUAL
WHERE @ch_id IS NOT NULL AND @gt_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM edu_question WHERE gate_id = @gt_id AND deleted = 0 AND sort_order = 102 AND JSON_CONTAINS(tags_json, '"TASK-20261122-002"'));
