INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'h3', @ch_id, @gt_id, 'DYNAMIC_TEMPLATE', 'SINGLE_CHOICE', '在 $\\triangle ABC$ 中，内角 $A = 60^\\circ$，对边 $a = {{k}}$，则 $b + c$ 的最大值等于（  ）', '[]', '{"index":0}', '由余弦定理 ${{k}}^2 = b^2 + c^2 - bc = (b + c)^2 - 3bc \\ge (b + c)^2 - \\frac{3}{4}(b + c)^2 = \\frac{1}{4}(b + c)^2$，当 $b = c = {{k}}$ 时取等号，故 $b + c$ 最大值为 ${{2*k}}$。', NULL, '{"type":"PARAM_TEMPLATE","vars":{"k":[2,6]},"stemTpl":"在 $\\\\triangle ABC$ 中，内角 $A = 60^\\\\circ$，对边 $a = {{k}}$，则 $b + c$ 的最大值等于（  ）","ansExpr":"2 * k","wrongExprs":["k","3 * k","4 * k"]}', 4, '["解三角形周长均值不等式最值","TASK-20261122-002"]', '{"diagram":{"title":"△ABC 示意图","width":320,"height":210,"primitives":[{"type":"polygon","points":[[148,32],[56,172],[264,172]],"color":"#1E293B","fillColor":"#38BDF8"},{"type":"text","x":142,"y":12,"text":"A","color":"#1E293B"},{"type":"text","x":40,"y":174,"text":"B","color":"#1E293B"},{"type":"text","x":268,"y":174,"text":"C","color":"#1E293B"}]}}', 'ADMIN', 1, 104, 1, NULL, 0 FROM DUAL
