INSERT INTO edu_question (grade_code, chapter_id, gate_id, question_mode, question_format, stem, options_json, answer_json, analysis, generator_code, template_rule_json, difficulty, tags_json, ext_json, source, version, sort_order, enabled, created_by, deleted)
SELECT 'h3', @ch_id, @gt_id, 'STATIC', 'ESSAY', '已知正项数列 $\\{a_n\\}$ 的前 $n$ 项和为 $S_n$，且满足 $2S_n = a_n^2 + a_n$（$n \\in N^*$）。\n(1) 求数列 $\\{a_n\\}$ 的通项公式；\n(2) 设 $b_n = \\frac{1}{a_n a_{n+1}}$，求数列 $\\{b_n\\}$ 的前 $n$ 项和 $T_n$。', '[]', '{"text":"解：\\n(1) 当 $n = 1$ 时，$2a_1 = a_1^2 + a_1$，由 $a_1 > 0$ 得 $a_1 = 1$。\\n当 $n \\\\ge 2$ 时，$2S_{n-1} = a_{n-1}^2 + a_{n-1}$，两式相减得：\\n$2a_n = a_n^2 - a_{n-1}^2 + a_n - a_{n-1}$，\\n移项整理：$(a_n + a_{n-1})(a_n - a_{n-1} - 1) = 0$。\\n因为数列各项均为正数，$a_n + a_{n-1} > 0$，故 $a_n - a_{n-1} = 1$。\\n所以 $\\\\{a_n\\\\}$ 是首项为 $1$、公差为 $1$ 的等差数列，通项公式为 $a_n = n$。\\n(2) 由(1)得 $b_n = \\\\frac{1}{n(n + 1)} = \\\\frac{1}{n} - \\\\frac{1}{n + 1}$，\\n因此 $T_n = \\\\left(1 - \\\\frac{1}{2}\\\\right) + \\\\left(\\\\frac{1}{2} - \\\\frac{1}{3}\\\\right) + \\\\dots + \\\\left(\\\\frac{1}{n} - \\\\frac{1}{n + 1}\\\\right) = 1 - \\\\frac{1}{n + 1} = \\\\frac{n}{n + 1}$。"}', '【得分要点】(1) 由 $S_n$ 与 $a_n$ 递推作差并因式分解出 $a_n - a_{n-1} = 1$；(2) 裂项相消准确求和得 $\\frac{n}{n + 1}$。', NULL, NULL, 4, '["Sn与an递推关系及裂项求和","手写解答","TASK-20261122-002"]', NULL, 'ADMIN', 1, 105, 1, NULL, 0 FROM DUAL
WHERE @ch_id IS NOT NULL AND @gt_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM edu_question WHERE gate_id = @gt_id AND deleted = 0 AND sort_order = 105 AND JSON_CONTAINS(tags_json, '"TASK-20261122-002"'));

-- 同步各关卡抽题总数与通关门槛（基础/中档/压轴须答对3题，含1道解答+3道选择的拓展关须答对2道选择题）
UPDATE edu_gate gt JOIN (SELECT gate_id, COUNT(*) AS cnt FROM edu_question WHERE deleted = 0 AND enabled = 1 GROUP BY gate_id) q ON gt.id = q.gate_id SET gt.question_count = q.cnt, gt.pass_count = CASE WHEN gt.gate_index = 2 THEN LEAST(2, q.cnt) ELSE LEAST(3, q.cnt) END WHERE gt.deleted = 0;

COMMIT;
